function icon(n,cls='icon'){return `<svg class="${cls}" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${ICONS[n]||ICONS.info}</svg>`}
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const rp=n=>`Rp${Number(n||0).toLocaleString('id-ID')}`;
const cap=s=>String(s).charAt(0).toUpperCase()+String(s).slice(1);
const initials=s=>String(s||'').split(/\s+/).filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const monthLabel=ym=>{const [y,m]=ym.split('-').map(Number);return `${MONTHS[m-1]} ${y}`};
const shortDate=iso=>{let d=new Date(iso);return Number.isNaN(+d)?'-':new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',day:'numeric',month:'short',year:'numeric'}).format(d)};
const shortTime=iso=>{let d=new Date(iso);return Number.isNaN(+d)?'-':new Intl.DateTimeFormat('id-ID',{timeZone:'Asia/Jakarta',hour:'2-digit',minute:'2-digit'}).format(d)};
const uid=prefix=>`${prefix}-${Date.now().toString(36)}-${Math.floor(Math.random()*999999).toString(36)}`;
function seed(){
 const defs=[['u1','Raka Pratama','240000001','2024','member','RP'],['u2','Nadia Aryani','240000002','2024','member','NA'],['u3','Bima Satria','240000003','2024','member','BS'],['u4','Alya Kirana','230000004','2023','member','AK'],['u5','Hana Putri','230000005','2023','treasurer','HP'],['u6','Kirana Laras','220000006','2022','chair','KL'],['u7','Dimas Aditya','240000007','2024','member','DA'],['u8','Farah Safitri','230000008','2023','member','FS'],['u9','Naufal Malik','240000009','2024','member','NM'],['u10','Amira Zahra','220000010','2022','member','AZ']];
 const users=defs.map(([id,name,nim,year,role])=>({id,name,nickname:name.split(' ')[0],nim,year,role,initials:initials(name),active:true,avatar:'',wa:'62812345678'+id.slice(1)}));
 const obligations=[],payments=[];let paynum=1;
 users.forEach((u,ix)=>{
  for(let m=1;m<=10;m++){
   const mo=`2026-${String(m).padStart(2,'0')}`;
   const isPaid=m<=8||m===9&&ix!==0&&ix!==6&&ix!==8||m===10&&[1,2,3,4,5,7].includes(ix);
   const isPending=u.id==='u7'&&m===10;
   const fine=isPaid?0:((m<=10)?60000:0);
   const due={id:`ob-${u.id}-${mo}`,userId:u.id,month:mo,base:10000,fine,status:isPaid?'paid':'due'};
   obligations.push(due);
   if(isPaid){let day=m===10?(ix===1?1:ix===2?2:ix===3?3:ix===4?4:ix===5?5:6):Math.max(1,ix+2);const date=`2026-${String(m).padStart(2,'0')}-${String(day).padStart(2,'0')}T0${Math.min(ix+1,9)}:15:00+07:00`;payments.push({id:`TRX-${String(paynum++).padStart(5,'0')}`,userId:u.id,obligationIds:[due.id],amount:10000,paidAt:date,verifiedAt:date,status:'verified',method:'QRIS (contoh)',reference:'SIM-'+String(paynum).padStart(7,'0')});}
  }
 });
 return {theme:'light',sessionActive:true,userId:'u1',users,obligations,payments,intents:[{id:'PAY-DEMO-001',userId:'u7',obligationIds:['ob-u7-2026-10'],amount:70000,status:'pending',createdAt:'2026-10-16T09:14:00+07:00',reference:'SIM-DEMO-8872'}],notifications:[{id:'n1',userId:'u1',title:'Kas Oktober sudah jatuh tempo',body:'Tanggal 15 sudah lewat. Periksa kembali rincian iuran dan denda.',read:false,date:'2026-10-16T08:00:00+07:00'},{id:'n2',userId:'u1',title:'Tagihan September belum lunas',body:'Tunggakan September masih tercatat pada akunmu.',read:false,date:'2026-10-01T08:00:00+07:00'}],tickets:[],expenses:[{id:'EXP-01',title:'Konsumsi rapat pengurus',amount:150000,date:'2026-10-11',status:'approved',by:'u5'}],proposals:[],audit:[{id:'log1',text:'Basis data simulasi dimuat',by:'Sistem demo',date:'2026-10-16T09:00:00+07:00'}],prefs:{anonymous:false,quiet:true}};
}
let db;try{db=JSON.parse(localStorage.getItem(KEY)||'null')||seed();if(!db.users||!db.obligations)db=seed()}catch{db=seed()}
if(db.sessionActive===undefined)db.sessionActive=true;db.users.forEach(u=>{if(!u.nickname)u.nickname=u.name.split(' ')[0]||'Anggota'});
function save(){try{localStorage.setItem(KEY,JSON.stringify(db))}catch(e){console.warn('Penyimpanan browser penuh',e)}}
function user(){return db.users.find(u=>u.id===db.userId)||db.users[0]}
const GLASS_STYLES={"none":{"name":"Solid","blur":0,"description":"Tanpa kaca; paling hemat daya"},"satin":{"name":"Satin","blur":8,"description":"Lembut dan nyaris solid"},"frost":{"name":"Frost","blur":16,"description":"Kaca matte seimbang"},"crystal":{"name":"Crystal","blur":22,"description":"Lebih transparan dengan kilau halus"}};
function glassPrefs(){
 const u=user();
 if(!u.appearance||typeof u.appearance!=="object")u.appearance={glassStyle:"frost",glassBlur:16};
 if(!Object.hasOwn(GLASS_STYLES,u.appearance.glassStyle))u.appearance.glassStyle="frost";
 const n=Number(u.appearance.glassBlur);
 u.appearance.glassBlur=Number.isFinite(n)?Math.max(0,Math.min(28,Math.round(n/2)*2)):16;
 return u.appearance;
}
function applyGlass(){
 const pref=glassPrefs(),root=document.documentElement;
 root.dataset.glass=pref.glassStyle;
 root.style.setProperty("--glass-blur",`${pref.glassStyle==="none"?0:pref.glassBlur}px`);
}
function setGlassPreset(style){
 if(!Object.hasOwn(GLASS_STYLES,style))return;
 const pref=glassPrefs();pref.glassStyle=style;
 if(style!=="none")pref.glassBlur=GLASS_STYLES[style].blur;
 applyGlass();save();render(false);
 toast(style==="none"?"Efek kaca dimatikan.":`Gaya ${GLASS_STYLES[style].name} diterapkan untuk akun ini.`);
}
function setGlassBlur(value){
 const n=Number(value);if(!Number.isFinite(n))return;
 const pref=glassPrefs();if(pref.glassStyle==="none")return;
 pref.glassBlur=Math.max(0,Math.min(28,Math.round(n/2)*2));
 applyGlass();save();
 const label=document.getElementById("glass-blur-value");
 if(label)label.textContent=`${pref.glassBlur} px`;
 const mirror=document.getElementById("glass-current-strength");
 if(mirror)mirror.textContent=`${pref.glassBlur} px`;
 const slider=document.getElementById("glass-blur-slider");
 if(slider)slider.style.setProperty("--range-progress",`${pref.glassBlur/28*100}%`);
}
applyGlass();

const roleName=r=>r==='chair'?'Ketua Himpunan':r==='treasurer'?'Bendahara':'Anggota';
const roleSubline=r=>r==='chair'?'Ruang kepemimpinan dan keputusan':r==='treasurer'?'Ruang kerja dan verifikasi kas':'Ruang kas pribadimu';
const welcomeName=u=>u.nickname||u.name.split(' ')[0]||'Teman';
function hasStaff(){return ['treasurer','chair'].includes(user().role)}
function isChair(){return user().role==='chair'}
function owes(uId=user().id){return db.obligations.filter(x=>x.userId===uId&&x.status!=='paid'&&x.status!=='waived').sort((a,b)=>a.month.localeCompare(b.month))}
function totalDue(uId=user().id){return owes(uId).reduce((a,o)=>a+o.base+o.fine,0)}
function paidFor(uId=user().id){return db.payments.filter(p=>p.userId===uId&&p.status==='verified').sort((a,b)=>new Date(b.paidAt)-new Date(a.paidAt))}
function lb(ym='2026-10'){return db.payments.filter(x=>x.status==='verified'&&x.obligationIds.some(id=>db.obligations.find(o=>o.id===id)?.month===ym)).sort((a,b)=>new Date(a.paidAt)-new Date(b.paidAt)).map((p,i)=>({...p,rank:i+1,u:db.users.find(x=>x.id===p.userId)}))}
function owingStatus(o){return o.status==='paid'?'paid':o.status==='waived'?'waived':db.intents.some(t=>t.userId===o.userId&&t.status==='pending'&&t.obligationIds.includes(o.id))?'pending':o.fine?'late':'due'}
function toast(s){const root=document.getElementById('toast-root');root.innerHTML=`<div class="toast" role="status">${esc(s)}</div>`;setTimeout(()=>{if(root)root.innerHTML=''},4000)}
function audit(text){db.audit.unshift({id:uid('log'),text,by:user().name,date:new Date().toISOString()});save()}
function avatar(u,cl='mini-avatar'){return `<span class="${cl}" aria-label="Avatar ${esc(u.name)}">${u.avatar?`<img alt="" src="${u.avatar}"/>`:esc(initials(u.name))}</span>`}
function badgeStatus(s){const map={paid:['success','Lunas'],verified:['success','Terverifikasi'],pending:['warn','Menunggu'],due:['neutral','Belum dibayar'],late:['danger','Terlambat'],rejected:['danger','Ditolak'],waived:['neutral','Dikecualikan'],approved:['success','Disetujui'],submitted:['warn','Diajukan'],open:['warn','Terbuka'],closed:['success','Selesai']};const [c,t]=map[s]||['neutral',cap(s)];return `<span class="pill ${c}">${t}</span>`}
function setTheme(v){db.theme=v;document.documentElement.dataset.theme=v;save();render(false)}
document.documentElement.dataset.theme=db.theme||'light';
const navMember=[['Beranda','/app','house'],['Leaderboard','/app/leaderboard','trophy'],['Bayar kas','/app/tagihan','wallet'],['Riwayat','/app/riwayat','history'],['Notifikasi','/app/notifikasi','bell'],['Profil','/app/profil','user'],['Pengaturan','/app/pengaturan','settings'],['Bantuan','/app/bantuan','help']];
const navStaff=[['Ringkasan','/pengurus/keuangan','house'],['Verifikasi','/pengurus/verifikasi','checkbook'],['Anggota','/pengurus/anggota','users'],['Tunggakan','/pengurus/tunggakan','alert'],['Reminder','/pengurus/reminder','send'],['Buku kas','/pengurus/buku-kas','receipt'],['Laporan','/pengurus/laporan','chart'],['Sengketa','/pengurus/sengketa','help']];
const navChair=[['Persetujuan','/pengurus/persetujuan','shield'],['Periode','/pengurus/periode','calendar'],['Keanggotaan','/pengurus/keanggotaan','users'],['Kebijakan','/pengurus/kebijakan','settings'],['Hak akses','/pengurus/akses','lock'],['Audit & operasi','/pengurus/audit','clipboard']];
function route(){return decodeURI((location.hash||'#/app').slice(1).split('?')[0])}
function head(title,subtitle='',extra=''){const r=route(),section=r.startsWith('/pengurus/')?'PENGELOLAAN':'PERSONAL',per=hasStaff()?'2026 / 27':'2026';return `<div class="page-head"><div><div class="eyebrow page-index">KASHIMA <span class="slash">/</span> ${section} <span class="slash">/</span> ${per}</div><h1>${esc(title)}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div>${extra?`<div class="page-side">${extra}</div>`:''}</div>`}
function labelRow(title,link='',label='Lihat semua'){return `<div class="label-row"><h2>${title}</h2>${link?`<a class="link-arrow" href="#${link}">${label} ${icon('arrow-right')}</a>`:''}</div>`}
function demoStrip(){return `<div class="demo-strip"><span class="demo-dot"></span><b>MODE PRATINJAU</b><span>Data contoh, bukan catatan pembayaran nyata.</span></div>`}
function nlink(item,r){const active=r===item[1]||r.startsWith(item[1]+'/')&&item[1]!='/app';return `<a class="side-link ${active?'active':''}" href="#${item[1]}">${icon(item[2])}<span>${item[0]}</span></a>`}
function sidebar(r){const me=user(),staff=hasStaff();const primary=staff?([['Ringkasan','/pengurus/keuangan','house'],['Verifikasi','/pengurus/verifikasi','checkbook'],['Anggota','/pengurus/anggota','users'],['Tunggakan','/pengurus/tunggakan','clock'],['Buku kas','/pengurus/buku-kas','wallet'],['Laporan','/pengurus/laporan','chart'],['Reminder','/pengurus/reminder','send']]):navMember.filter(x=>!['/app/notifikasi','/app/pengaturan','/app/bantuan','/app/profil'].includes(x[1]));return `<aside class="sidebar"><div class="sidebar-inner"><a href="#${staff?'/pengurus/keuangan':'/app'}" class="brand" aria-label="KasHima - beranda"><span class="brand-mark">k.</span><span><span class="brand-word">KasHima<span class="brand-period">.</span></span><span class="brand-caption">PRIVATE FINANCIAL SPACE</span></span></a><div class="side-role-label"><span class="side-role-orb"></span><span>${esc(roleName(me.role).toUpperCase())}</span></div><div class="side-section"><div class="side-heading">${staff?'Ruang kerja':'Navigasi pribadi'}</div>${primary.map(i=>nlink(i,r)).join('')}</div>${isChair()?`<div class="side-section"><div class="side-heading">Kepemimpinan</div>${[['Persetujuan','/pengurus/persetujuan','shield'],['Periode','/pengurus/periode','calendar'],['Keanggotaan','/pengurus/keanggotaan','users'],['Kebijakan','/pengurus/kebijakan','settings'],['Hak akses','/pengurus/akses','lock'],['Audit sistem','/pengurus/audit','database']].map(i=>nlink(i,r)).join('')}</div>`:staff?`<div class="side-section"><div class="side-heading">Pengelolaan</div>${[['Sengketa','/pengurus/sengketa','help'],['Leaderboard','/app/leaderboard','trophy']].map(i=>nlink(i,r)).join('')}</div>`:''}<div class="side-section side-utility"><div class="side-heading">Akun</div>${[['Profil saya','/app/profil','user'],['Pengaturan','/app/pengaturan','settings'],['Notifikasi','/app/notifikasi','bell']].map(i=>nlink(i,r)).join('')}</div></div><div class="side-bottom"><a class="side-info side-profile-link" href="#/app/profil" aria-label="Buka profil ${esc(me.name)}">${avatar(me)}<span class="side-person"><span class="side-user-label">${esc(welcomeName(me))}</span><span class="side-user-meta">${esc(roleName(me.role))}</span></span>${icon('chevron-right')}</a></div></aside>`}
function headerMobile(){const me=user();return `<header class="mobile-header"><a href="#${hasStaff()?'/pengurus/keuangan':'/app'}" class="brand" aria-label="Beranda KasHima"><span class="brand-mark">k.</span><span><span class="brand-word">KasHima<span class="brand-period">.</span></span><span class="brand-caption">${esc(roleName(me.role).toUpperCase())}</span></span></a><div class="top-actions"><button class="icon-button theme-quick" data-action="toggle-theme" aria-label="${db.theme==='dark'?'Aktifkan mode terang':'Aktifkan mode gelap'}">${icon(db.theme==='light'?'moon':'sun')}</button><a class="icon-button notifications-quick" href="#/app/notifikasi" aria-label="Notifikasi">${icon('bell')}</a><a class="top-avatar" href="#/app/profil" aria-label="Buka profil ${esc(me.name)}">${me.avatar?`<img src="${me.avatar}" alt=""/>`:esc(initials(me.name))}</a></div></header>`}
function mobileNav(r){const n=hasStaff()?(isChair()?[['Beranda','/pengurus/keuangan','house'],['Persetujuan','/pengurus/persetujuan','shield'],['Laporan','/pengurus/laporan','chart'],['Profil','/app/profil','user']]:[['Beranda','/pengurus/keuangan','house'],['Verifikasi','/pengurus/verifikasi','checkbook'],['Tunggakan','/pengurus/tunggakan','history'],['Profil','/app/profil','user']]):[['Beranda','/app','house'],['Ranking','/app/leaderboard','trophy'],['Bayar','/app/tagihan','wallet'],['Riwayat','/app/riwayat','history'],['Profil','/app/profil','user']];return `<nav class="mobile-nav ${hasStaff()?'mobile-nav-staff':'mobile-nav-member'}" aria-label="Navigasi utama untuk ${esc(roleName(user().role))}">${n.map(i=>`<a href="#${i[1]}" class="${r===i[1]||r.startsWith(i[1]+'/')&&i[1]!='/app'?'active':''}" ${r===i[1]?'aria-current="page"':''} aria-label="${i[0]}">${icon(i[2])}<span>${i[0]}</span></a>`).join('')}</nav>`}
function topbar(r){const labels=[...navMember,...navStaff,...navChair],me=user();const l=labels.find(x=>r===x[1])?.[0]||'Detail';return `<header class="desktop-topbar"><span class="topcrumb">RUANG ${esc(roleName(me.role).toUpperCase())}<span class="topcrumb-divider">/</span><strong>${esc(l)}</strong></span><div class="top-actions"><span class="header-edition">2026 <span class="serif">/</span> 2027</span><button class="icon-button" data-action="toggle-theme" aria-label="Ganti tema">${icon(db.theme==='light'?'moon':'sun')}</button><a class="icon-button" href="#/app/notifikasi" aria-label="Notifikasi">${icon('bell')}</a><a class="top-avatar" href="#/app/profil" aria-label="Buka profil ${esc(me.name)}">${me.avatar?`<img src="${me.avatar}" alt=""/>`:esc(initials(me.name))}</a></div></header>`}
function monthCells(uId){return db.obligations.filter(o=>o.userId===uId&&Number(o.month.slice(5))>=5).slice(-6).map(o=>{let s=owingStatus(o);return `<a href="#/app/tagihan" class="month-cell ${s==='paid'?'done':s==='late'?'late':'upcoming'}" aria-label="${monthLabel(o.month)}, ${s==='paid'?'lunas':'belum lunas'}"><span class="mname">${MONTHS[Number(o.month.slice(5))-1].slice(0,3)}</span><span class="mstatus">${icon(s==='paid'?'check':s==='late'?'alert':'clock')}</span></a>`}).join('')}
function dueRows(items,allowAction=false){return items.length?items.map(o=>`<div class="list-row"><div class="row-main"><span class="row-icon">${icon('calendar')}</span><span><div class="row-title">Kas ${monthLabel(o.month)}</div><div class="row-meta">Iuran ${rp(o.base)}${o.fine?` · Denda ${rp(o.fine)}`:''}</div></span></div><div class="row-right"><div class="row-amount">${rp(o.base+o.fine)}</div>${badgeStatus(owingStatus(o))}</div></div>`).join(''):`<div class="empty">${icon('check-circle')}<strong>Tidak ada tagihan terbuka</strong><p>Semua kewajiban pada contoh ini telah lunas.</p></div>`}
function recentPaymentRows(uid=user().id,max=4){const p=paidFor(uid).slice(0,max);return p.length?p.map(x=>`<a class="list-row" href="#/app/riwayat/${encodeURIComponent(x.id)}"><div class="row-main"><span class="row-icon">${icon('check')}</span><span><div class="row-title">Kas ${x.obligationIds.map(id=>db.obligations.find(o=>o.id===id)?.month).filter(Boolean).map(monthLabel).join(', ')}</div><div class="row-meta">${shortDate(x.paidAt)} · ${esc(x.method)}</div></span></div><div class="row-right"><div class="row-amount">${rp(x.amount)}</div>${badgeStatus('paid')}</div></a>`).join(''):`<div class="empty">${icon('history')}<strong>Belum ada riwayat</strong><p>Transaksi yang sudah diverifikasi akan muncul di sini.</p></div>`}
function previewPodium(compact=false){const list=lb('2026-10');const order=[list[1],list[0],list[2]];return `<div class="podium-board" ${compact?'style="padding-bottom:0"':''}><div class="float-top"><span class="eyebrow">TOP 3 / OKTOBER</span><span style="font-family:var(--serif);font-size:23px;color:var(--gold);font-style:italic">2026</span></div><div class="podium-wrap">${order.map((p,index)=>p?`<div class="podium-person ${p.rank===1?'first':p.rank===2?'second':'third'}"><div class="podium-avatar">${esc(initials(p.u?.name||'A'))}</div><span class="podium-name">${esc(p.u?.anonymous?'Anggota '+p.rank:p.u?.name.split(' ')[0]||'Anggota')}</span><span class="podium-time">${shortDate(p.paidAt)}</span><div class="podium-stand">${p.rank}</div></div>`:'<div class="podium-person"></div>').join('')}</div></div>`}
function pageHome(){const me=user(),due=owes(),total=totalDue(),paid=paidFor(),rank=lb().find(x=>x.userId===me.id)?.rank;return `${demoStrip()}<div class="page-head home-intro" style="margin-bottom:28px"><div><div class="eyebrow">JUMAT / 16 OKTOBER 2026</div><h1 style="margin-top:13px">Selamat ${greeting()}, <span class="serif">${esc(welcomeName(me))}.</span></h1><p>Pantau kasmu, tanpa perlu menebak-nebak.</p></div><div class="page-side">${badgeStatus(total?'late':'paid')}</div></div><div class="grid-main"><div class="stack"><section class="hero" aria-label="Total tagihan"><div class="hero-top"><span class="hero-overline">CATATAN KAS / 10.2026</span><span class="hero-seal">k.</span></div><div class="hero-mid"><span class="hero-small">Jumlah kewajiban yang masih terbuka</span><div class="hero-number"><span class="currency">Rp</span>${Number(total).toLocaleString('id-ID')}</div><div class="hero-sub">${due.length?`${due.length} periode masih terbuka · Iuran dan denda dirinci`: 'Tidak ada kewajiban yang tertunda'}</div></div><div class="hero-bottom"><button class="btn btn-light" data-action="init-pay" ${!total?'disabled':''}>${total?'Bayar kas sekarang':'Semua lunas'} ${icon('arrow-right')}</button><div class="hero-smallnote">${total?`<b>Lewat jatuh tempo</b><br/>15 Oktober 2026`:'<b>Tepat waktu</b><br/>Terima kasih'}</div></div></section><section>${labelRow('Catatan bulan ini','/app/tagihan','Rincian tagihan')}<div class="paper">${dueRows(due.slice(-3))}${due.length>3?`<a class="link-arrow" href="#/app/tagihan" style="padding-top:18px">Lihat ${due.length} bulan terbuka ${icon('arrow-right')}</a>`:''}</div></section><section>${labelRow('Jejak pembayaran','/app/riwayat','Semua riwayat')}<div class="paper">${recentPaymentRows(me.id,3)}</div></section></div><aside class="stack"><div class="split-metric"><span class="metric-kicker">Perjalananmu sejauh ini</span><div class="metric-value">${paid.length}<span class="serif" style="font-size:20px;color:var(--gold);margin-left:7px">bulan</span></div><div class="metric-foot">Pembayaran tervalidasi di data simulasi</div></div><section>${labelRow('Konsistensi bulanan')}<div class="right-summary"><div class="float-top" style="margin-bottom:19px"><span class="eyebrow">MEI - OKTOBER</span><span class="label-small">2026</span></div><div class="month-strip">${monthCells(me.id)}</div><div style="display:flex;gap:17px;margin-top:18px;font-size:10px;color:var(--muted)"><span><b style="color:var(--success)">●</b> Lunas</span><span><b style="color:var(--warn)">●</b> Menunggak</span></div></div></section><section>${labelRow('Paling disiplin','/app/leaderboard','Peringkat lengkap')}${previewPodium(true)}</section><div class="editorial-note"><span class="eyebrow">CATATAN KECIL</span><p>Keuangan yang rapi dimulai dari kebiasaan sederhana.</p></div></aside></div>`}
function pageDue(){const dues=db.obligations.filter(o=>o.userId===user().id).sort((a,b)=>b.month.localeCompare(a.month));const due=owes();return `${demoStrip()}${head('Tagihan kas','Detail kewajibanmu dari bulan ke bulan.',`<button class="btn btn-primary" data-action="init-pay" ${!due.length?'disabled':''}>Bayar ${rp(totalDue())} ${icon('arrow-right')}</button>`)}<div class="grid-main"><section class="stack"><div class="paper"><div class="float-top"><span class="eyebrow">SEMUA PERIODE 2026</span><span class="pill neutral">${dues.length} bulan tercatat</span></div><div class="divider"></div>${dues.map(o=>`<div class="list-row"><div class="row-main"><span class="row-icon">${icon(owingStatus(o)==='paid'?'check':'calendar')}</span><div><div class="row-title">${monthLabel(o.month)}</div><div class="row-meta">Jatuh tempo 15 ${MONTHS[Number(o.month.slice(5))-1]} 2026</div></div></div><div class="row-right"><div class="row-amount">${rp(o.base+o.fine)}</div>${badgeStatus(owingStatus(o))}</div></div>`).join('')}</div></section><aside class="stack"><div class="paper"><span class="eyebrow">RINCIAN KEWAJIBAN</span><div style="font-size:35px;letter-spacing:-1.5px;margin:10px 0">${rp(totalDue())}</div><div class="divider"></div><div class="details-list"><div class="detail-line"><span class="muted">Iuran pokok</span><strong>${rp(due.reduce((a,x)=>a+x.base,0))}</strong></div><div class="detail-line"><span class="muted">Denda tercatat</span><strong>${rp(due.reduce((a,x)=>a+x.fine,0))}</strong></div><div class="detail-line"><span class="muted">Bulan tertunggak</span><strong>${due.length}</strong></div></div><div class="divider"></div><button class="btn btn-primary btn-block" data-action="init-pay" ${!due.length?'disabled':''}>Lanjut ke pembayaran ${icon('arrow-right')}</button></div><div class="soft-note">${icon('info')}<span>Contoh aturan denda Rp60.000 per bulan terlambat. Kebijakan asli menunggu pengesahan himpunan.</span></div></aside></div>`}
function qrSample(seed){const size=27,cell=6;let hash=0;for(const c of seed)hash=((hash<<5)-hash+c.charCodeAt(0))|0;let bits='';const isFinder=(x,y,ox,oy)=>{const dx=x-ox,dy=y-oy;return dx>=0&&dx<7&&dy>=0&&dy<7&&(dx===0||dx===6||dy===0||dy===6||(dx>=2&&dx<=4&&dy>=2&&dy<=4))};for(let y=0;y<size;y++)for(let x=0;x<size;x++){const f=isFinder(x,y,0,0)||isFinder(x,y,20,0)||isFinder(x,y,0,20);hash=(hash*1664525+1013904223)|0;if(f||((hash>>>7)&3)===0){bits+=`<rect x="${x*cell}" y="${y*cell}" width="${cell}" height="${cell}"/>`}}return `<svg viewBox="0 0 ${size*cell} ${size*cell}" aria-label="Gambar pola ilustrasi, bukan QRIS sah"><rect width="100%" height="100%" fill="white"/><g fill="#203e35">${bits}</g><rect x="44" y="64" width="74" height="35" rx="4" fill="white" stroke="#aebbac"/><text x="81" y="80" text-anchor="middle" font-size="11" font-weight="800" fill="#285444">DEMO</text><text x="81" y="91" text-anchor="middle" font-size="6.5" fill="#486a59">BUKAN QRIS</text></svg>`}
function getIntent(id){return db.intents.find(t=>t.id===id)}
function ensureOwn(t){return t&&t.userId===user().id}
function paymentPage(id){const t=getIntent(id);if(!ensureOwn(t))return errorPage('Pembayaran tidak ditemukan','Kode transaksi ini bukan milik akun yang sedang aktif.','/app/tagihan');const obligations=t.obligationIds.map(id=>db.obligations.find(o=>o.id===id)).filter(Boolean);const sum=obligations.reduce((a,x)=>a+x.base+x.fine,0);return `${demoStrip()}<div style="margin-bottom:21px"><a class="link-arrow" href="#/app/tagihan">${icon('arrow-left')} Kembali ke tagihan</a></div>${head('Pembayaran kas','Pastikan kembali nominal yang akan dibayar.')}<div class="checkout"><div class="stack"><div class="paper"><div class="float-top"><span class="eyebrow">RINCIAN PEMBAYARAN</span><span class="pill neutral">${esc(t.id)}</span></div><div style="margin-top:26px"><div class="label-small">Total tagihan</div><div class="checkout-total">${rp(t.amount)}</div></div><div class="divider"></div>${obligations.map(o=>`<div class="detail-line" style="margin:13px 0"><div><strong>Kas ${monthLabel(o.month)}</strong><div class="label-small">Pokok ${rp(o.base)}${o.fine?` · Denda ${rp(o.fine)}`:''}</div></div><strong>${rp(o.base+o.fine)}</strong></div>`).join('')}<div class="divider"></div><div class="detail-line"><strong>Total dibayar</strong><strong>${rp(sum)}</strong></div></div></div><aside class="qr-area"><span class="qr-label">QRIS / PRATINJAU</span><div class="qr-wrap">${qrSample(t.id)}</div><strong style="font-size:13px">Tidak dapat dipakai membayar</strong><p class="qr-foot">Gambar ini hanya menunjukkan posisi QR pada desain. Identitas merchant dan QRIS produksi masih harus divalidasi.</p><div class="divider"></div><div class="detail-line"><span class="muted">Nominal</span><strong>${rp(t.amount)}</strong></div><div class="detail-line" style="margin-top:12px"><span class="muted">Penerima</span><strong>Belum terhubung</strong></div><button class="btn btn-outline btn-block" style="margin-top:21px" data-action="save-qr-preview" data-id="${esc(t.id)}">${icon('download')} Simpan pratinjau QR</button></aside></div><div class="payment-instructions"><div class="soft-note warning">${icon('alert')}<span>QR yang terlihat adalah ilustrasi. Belum terhubung ke akun merchant resmi, sehingga tidak dapat digunakan mengirim uang.</span></div><div class="paper"><h3 style="margin-bottom:7px">Alur setelah pembayaran</h3><p class="muted" style="font-size:12px">Di sistem nyata, status sukses hanya boleh muncul setelah informasi transaksi dari sumber resmi berhasil diverifikasi.</p><div class="progress-steps"><span class="progress-step done">01 · Tagihan</span><span class="progress-step current">02 · Pembayaran</span><span class="progress-step">03 · Konfirmasi</span></div><button class="btn btn-outline btn-block" data-action="demo-submit" data-id="${esc(t.id)}">Simulasikan pengajuan pembayaran ${icon('arrow-right')}</button></div></div>`}
function pagePending(id){const t=getIntent(id);if(!ensureOwn(t))return errorPage('Pembayaran tidak ditemukan','Silakan buka daftar tagihan akunmu.','/app/tagihan');if(t.status==='verified'){setTimeout(()=>{location.hash=`#/app/bayar/${id}/berhasil`},50);return ''}return `${demoStrip()}${head(t.status==='rejected'?'Konfirmasi perlu diperbaiki':'Menunggu konfirmasi','Status diperbarui setelah pemeriksaan benar-benar selesai.')}<div class="paper receipt-card" style="text-align:center"><div class="waiting-anim" aria-hidden="true"></div><div class="eyebrow">TRANSAKSI ${esc(t.id)}</div><h2 class="serif" style="font-size:32px;margin:17px 0 9px">${t.status==='rejected'?'Belum dapat disetujui':'Pengajuanmu sudah tercatat.'}</h2><p class="muted" style="max-width:370px;margin:0 auto 19px;font-size:13px">${t.status==='rejected'?'Informasi tidak sesuai. Hubungi bendahara untuk melihat alasan dan memperbaikinya.':'Dalam pratinjau ini, bendahara perlu meninjau pengajuan sebelum status berubah menjadi berhasil.'}</p><div class="receipt-amount">${rp(t.amount)}</div><div class="progress-steps"><span class="progress-step done">01 · Tagihan</span><span class="progress-step done">02 · Diajukan</span><span class="progress-step current">03 · Verifikasi</span></div><div class="soft-note" style="text-align:left">${icon('info')}<span>Tombol pengajuan bukan bukti pembayaran uang masuk. Pratinjau ini menyimpan status di browser dan tidak menghubungi bank atau merchant.</span></div><div class="mini-stack" style="margin-top:24px"><button class="btn btn-primary btn-block" data-action="switch-user">Buka akun bendahara demo ${icon('arrow-right')}</button><button class="btn btn-outline btn-block" data-action="refresh">Perbarui status</button><a class="btn btn-text" href="#/app/riwayat">Lihat riwayat</a></div></div>`}
function pageSuccess(id){const t=getIntent(id);if(!ensureOwn(t))return errorPage('Pembayaran tidak ditemukan','Cek kembali akun yang digunakan.','/app/tagihan');if(t.status!=='verified')return pagePending(id);const pay=db.payments.find(p=>p.intentId===t.id);if(!pay)return errorPage('Bukti belum tersedia','Data transaksi masih perlu diperiksa oleh sistem demo.','/app/riwayat');return `${demoStrip()}<div class="paper receipt-card"><div class="success-stamp">${icon('check')}</div><span class="eyebrow">BUKTI TRANSAKSI DEMO</span><h1 style="font-size:34px;margin:14px 0 6px">Pembayaran tercatat.</h1><p class="muted" style="font-size:12px">Disetujui dalam simulasi bendahara. Tidak mewakili transaksi QRIS sungguhan.</p><div class="receipt-amount">${rp(pay.amount)}</div>${badgeStatus('paid')}<div class="divider"></div><div class="details-list receipt-lines"><div class="detail-line"><span class="muted">Nomor bukti</span><strong>${esc(pay.id)}</strong></div><div class="detail-line"><span class="muted">Periode</span><strong>${pay.obligationIds.map(x=>monthLabel(db.obligations.find(y=>y.id===x)?.month||'2026-10')).join(', ')}</strong></div><div class="detail-line"><span class="muted">Tanggal disetujui</span><strong>${shortDate(pay.verifiedAt)}</strong></div><div class="detail-line"><span class="muted">Metode</span><strong>Simulasi verifikasi</strong></div></div><div class="mini-stack"><button class="btn btn-primary btn-block" data-action="print">${icon('download')} Cetak atau simpan PDF</button><a class="btn btn-outline btn-block" href="#/app/riwayat/${encodeURIComponent(pay.id)}">Lihat detail transaksi</a><a class="btn btn-text" href="#/app">Kembali ke beranda</a></div></div>`}
function historyPage(){const list=paidFor();return `${demoStrip()}${head('Riwayat pembayaran','Setiap pembayaran yang sudah divalidasi tercatat di sini.')}<div class="grid-main"><div class="paper"><div class="float-top"><span class="eyebrow">PEMBAYARAN TERVERIFIKASI</span><span class="pill">${list.length} transaksi</span></div><div class="divider"></div>${recentPaymentRows(user().id,50)}</div><aside class="stack"><div class="paper"><span class="eyebrow">REKAP AKUN</span><div class="metric-value" style="margin:16px 0 6px">${rp(list.reduce((s,p)=>s+p.amount,0))}</div><div class="metric-foot">Total kas yang tercatat lunas (data contoh)</div><div class="divider"></div><div class="detail-line"><span class="muted">Bulan lunas</span><strong>${list.length}</strong></div><div class="detail-line" style="margin-top:15px"><span class="muted">Perlu dibayar</span><strong>${rp(totalDue())}</strong></div></div><div class="soft-note">${icon('shield')}<span>Riwayat dibedakan antara status tercatat dan verifikasi bank. Dalam produksi, hanya pembayaran dengan bukti sah yang masuk laporan.</span></div></aside></div>`}
function paymentDetail(id){const p=db.payments.find(x=>x.id===id&&x.userId===user().id);if(!p)return errorPage('Riwayat tidak ditemukan','Transaksi tidak tersedia untuk akun ini.','/app/riwayat');return `${demoStrip()}<a href="#/app/riwayat" class="link-arrow">${icon('arrow-left')} Kembali ke riwayat</a><div style="height:21px"></div>${head('Detail transaksi','Bukti pencatatan untuk pembayaran yang dipilih.') }<div class="paper" style="max-width:700px"><div class="float-top"><span class="eyebrow">RINCIAN TRANSAKSI</span>${badgeStatus('paid')}</div><div style="font-size:39px;letter-spacing:-1.7px;margin:19px 0">${rp(p.amount)}</div><div class="divider"></div><div class="details-list"><div class="detail-line"><span class="muted">Nomor transaksi</span><strong>${esc(p.id)}</strong></div><div class="detail-line"><span class="muted">Tanggal pembayaran</span><strong>${shortDate(p.paidAt)}</strong></div><div class="detail-line"><span class="muted">Periode kas</span><strong>${p.obligationIds.map(x=>monthLabel(db.obligations.find(y=>y.id===x)?.month||'2026-10')).join(', ')}</strong></div><div class="detail-line"><span class="muted">Metode</span><strong>${esc(p.method)}</strong></div><div class="detail-line"><span class="muted">Keterangan</span><strong>${p.intentId?'Demo diverifikasi bendahara':'Data contoh awal'}</strong></div></div><div class="divider"></div><button class="btn btn-primary" data-action="print">${icon('download')} Simpan bukti PDF</button></div>`}
function leaderboardPage(){const entries=lb(),my=entries.find(x=>x.userId===user().id),s=entries.slice(3);return `${demoStrip()}${head('Leaderboard','Konsistensi kecil, dihargai setiap bulan.')}<div class="grid-main"><div class="stack"><div class="float-top"><div><div class="eyebrow">PERINGKAT BULANAN</div><h2 style="margin:8px 0 0">Oktober <span class="serif">2026</span></h2></div><span class="pill">${entries.length} anggota lunas</span></div>${previewPodium()}<section>${labelRow('Daftar peringkat')}<div class="paper">${s.length?s.map(p=>`<div class="rank-row"><span class="rank-no">${p.rank}</span>${avatar(p.u,'avatar sm')}<span class="rank-name">${esc(p.u.anonymous?'Anggota '+p.rank:p.u.name)}</span><span class="rank-time">${shortDate(p.paidAt)}</span></div>`).join(''):`<div class="soft-note">${icon('info')}<span>Anggota berikutnya muncul setelah ada pembayaran yang diverifikasi.</span></div>`}</div></section></div><aside class="stack"><div class="paper"><div class="eyebrow">POSISIMU</div><div class="metric-value" style="font-size:45px;margin:15px 0">${my?'#'+my.rank:'—'}</div><p class="muted" style="font-size:12px">${my?'Terima kasih sudah menyelesaikan kas bulan ini.':'Peringkat bulan ini akan muncul setelah kas bulan berjalan lunas dan terverifikasi.'}</p><div class="divider"></div><div class="detail-line"><span class="muted">Periode aktif</span><strong>Oktober 2026</strong></div><div class="detail-line" style="margin-top:12px"><span class="muted">Dasar urutan</span><strong>Waktu terverifikasi</strong></div></div><div class="soft-note">${icon('shield')}<span>Leaderboard tidak menampilkan jumlah tunggakan atau NIM milik anggota lain. Ini simulasi dengan data contoh.</span></div></aside></div>`}
function notifPage(){const n=db.notifications.filter(x=>x.userId===user().id).sort((a,b)=>new Date(b.date)-new Date(a.date));return `${demoStrip()}${head('Notifikasi','Perubahan penting di satu tempat.')}<div class="paper" style="max-width:800px"><div class="float-top"><span class="eyebrow">PUSAT INFORMASI</span><button class="btn btn-text btn-small" data-action="mark-read">Tandai sudah dibaca</button></div><div class="divider"></div>${n.length?n.map(x=>`<div class="list-row"><div class="row-main"><span class="row-icon">${icon(x.read?'check':'bell')}</span><div><div class="row-title">${esc(x.title)} ${x.read?'':'<span style="color:var(--gold)">●</span>'}</div><div class="row-meta">${esc(x.body)}</div><div class="row-meta" style="margin-top:5px">${shortDate(x.date)}</div></div></div></div>`).join(''):`<div class="empty">${icon('bell')}<strong>Belum ada notifikasi</strong><p>Semua pengingat penting akan muncul di sini.</p></div>`}</div>`}
function profilePage(){
 const me=user(),paid=paidFor(me.id).length,rank=lb().find(x=>x.userId===me.id)?.rank,staff=hasStaff(),role=roleName(me.role);
 const quick=me.role==='chair'?[['Keputusan menunggu','/pengurus/persetujuan','shield'],['Laporan keuangan','/pengurus/laporan','chart'],['Kelola hak akses','/pengurus/akses','users']]:me.role==='treasurer'?[['Verifikasi pembayaran','/pengurus/verifikasi','checkbook'],['Tunggakan anggota','/pengurus/tunggakan','history'],['Buku kas','/pengurus/buku-kas','wallet']]:[['Riwayat pembayaran','/app/riwayat','history'],['Tagihan kas','/app/tagihan','wallet'],['Leaderboard','/app/leaderboard','trophy']];
 const stat=staff?me.role==='chair'?String(db.proposals.filter(x=>x.status==='submitted').length).padStart(2,'0'):String(db.intents.filter(x=>x.status==='pending').length).padStart(2,'0'):String(paid).padStart(2,'0');
 const statCaption=me.role==='chair'?'Usulan menunggu keputusan':me.role==='treasurer'?'Pengajuan menunggu verifikasi':'Pembayaran kas tercatat pada data demo';
 return `${demoStrip()}
 <main class="account-page role-${me.role}" aria-labelledby="account-heading">
  <header class="account-heading">
   <div><span class="account-kicker">KASHIMA <span aria-hidden="true">/</span> AKUN PRIBADI</span><h1 id="account-heading">Profil <em>saya.</em></h1><p>Identitas dan aksesmu, tertata dalam satu tempat.</p></div>
   <span class="account-period">PERIODE <strong>2026 / 27</strong></span>
  </header>
  <section class="account-overview" aria-label="Identitas utama">
   <div class="account-portrait">
    <button class="identity-avatar" type="button" data-action="pick-avatar" aria-label="Ganti foto profil">${me.avatar?`<img src="${me.avatar}" alt="Foto profil ${esc(me.name)}"/>`:`<span>${esc(initials(me.name))}</span>`}<span class="identity-avatar-camera">${icon('camera')}</span></button>
   </div>
   <div class="account-name-wrap"><p class="account-role-line"><span class="account-role-dot" aria-hidden="true"></span>${esc(role)} <span class="account-role-divider" aria-hidden="true">/</span> Himpunan Mahasiswa</p><h2>${esc(me.name)}</h2><p class="account-nickname">Panggil saja <strong>${esc(welcomeName(me))}</strong></p><p class="account-nim">NIM ${esc(me.nim)} <span aria-hidden="true">·</span> Angkatan ${esc(me.year)}</p></div>
   <div class="account-portrait-actions"><button type="button" class="account-action-link" data-action="pick-avatar">${icon('camera')} ${me.avatar?'Ganti foto':'Tambah foto'}</button>${me.avatar?`<button type="button" class="account-action-link account-action-remove" data-action="remove-avatar">${icon('trash')} Hapus foto</button>`:''}</div>
   <input id="avatar-picker" type="file" accept="image/png,image/jpeg,image/webp" hidden aria-label="Pilih foto profil">
  </section>
  <div class="account-layout">
   <div class="account-primary">
    <section class="account-section account-personal" aria-labelledby="account-personal-title">
     <div class="account-section-heading"><div><span class="account-section-index">01 / IDENTITAS</span><h3 id="account-personal-title">Informasi diri</h3></div><button type="button" class="account-edit-link" data-action="edit-profile">Ubah identitas ${icon('arrow-right')}</button></div>
     <div class="account-info-list"><div class="profile-information-row"><span>Nama lengkap</span><strong>${esc(me.name)}</strong></div><div class="profile-information-row"><span>Nama panggilan</span><strong>${esc(welcomeName(me))}</strong></div><div class="profile-information-row"><span>NIM</span><strong class="tabular">${esc(me.nim)}</strong></div><div class="profile-information-row"><span>Angkatan</span><strong>${esc(me.year)}</strong></div><div class="profile-information-row"><span>Peran aktif</span><strong>${esc(role)}</strong></div></div>
    </section>
    <section class="account-section account-shortcuts" aria-labelledby="account-shortcuts-title">
     <div class="account-section-heading"><div><span class="account-section-index">02 / NAVIGASI</span><h3 id="account-shortcuts-title">Akses cepat ${staff?'pengurus':'pribadi'}</h3></div></div>
     <div class="profile-quicklinks">${quick.map(x=>`<a class="profile-quicklink" href="#${x[1]}"><span class="account-shortcut-icon">${icon(x[2])}</span><span class="quick-label">${x[0]}</span>${icon('arrow-right')}</a>`).join('')}</div>
    </section>
   </div>
   <aside class="account-secondary" aria-label="Ringkasan dan keamanan akun">
    <section class="profile-stats account-summary" aria-label="Ringkasan akun"><span class="account-section-index">${staff?'STATUS PENGURUS':'RINGKASAN AKUN'}</span><div class="account-summary-main"><span class="profile-stat-value">${stat} <span class="serif">${staff?'agenda':'bulan'}</span></span><p class="profile-stat-caption">${statCaption}</p></div><div class="account-summary-sub"><div class="profile-stat-line"><span>${staff?'Status akses':'Peringkat Oktober'}</span><strong>${staff?'Aktif · '+esc(role):rank?'#'+rank:'Belum masuk'}</strong></div><div class="profile-stat-line"><span>${staff?'Periode':'Tagihan terbuka'}</span><strong>${staff?'2026 / 2027':rp(totalDue())}</strong></div></div></section>
    <section class="profile-security account-security" aria-labelledby="account-security-title">
     <div class="account-section-heading"><div><span class="account-section-index">03 / AKUN</span><h3 id="account-security-title">Keamanan & preferensi</h3></div></div>
     <a href="#/app/pengaturan" class="settings-item"><span>${icon('settings')} Pengaturan tampilan</span>${icon('chevron-right')}</a><a href="#/app/bantuan" class="settings-item"><span>${icon('help')} Bantuan akun</span>${icon('chevron-right')}</a><button type="button" class="settings-item profile-switch" data-action="switch-user"><span>${icon('arrows')} Ganti akun demo</span>${icon('chevron-right')}</button>
     <button type="button" class="profile-logout" data-action="logout">${icon('logout')} Keluar dari akun ${icon('arrow-right')}</button>
     <p class="profile-privacy-note">${icon('lock')} Perubahan profil hanya disimpan pada browser demo ini, tidak tersinkron ke perangkat lain.</p>
    </section>
   </aside>
  </div>
 </main>`;
}

function glassStudio(){
 const pref=glassPrefs(),off=pref.glassStyle==="none",current=GLASS_STYLES[pref.glassStyle];
 const choices=[["none","Solid","Tanpa blur"],["satin","Satin","Halus & lembut"],["frost","Frost","Seimbang"],["crystal","Crystal","Lebih jernih"]];
 return `<section class="glass-studio" aria-labelledby="glass-studio-heading">
 <div class="glass-studio-head"><div><span class="eyebrow">PERSONALISASI VISUAL / GLASS STUDIO</span><h2 id="glass-studio-heading">Tentukan karakter <em>kacamu.</em></h2><p>Pilih jenis kaca, lalu geser tingkat blur. Perubahan langsung terlihat pada antarmukamu.</p></div><span class="glass-monogram" aria-hidden="true">g.</span></div>
 <div class="glass-presets" role="group" aria-label="Jenis glassmorphism">${choices.map(([id,name,detail])=>`<button class="glass-preset ${pref.glassStyle===id?"chosen":""}" data-action="glass-preset" data-id="${id}" type="button" aria-pressed="${pref.glassStyle===id}"><span class="glass-preset-sample sample-${id}" aria-hidden="true"><span></span></span><strong>${name}</strong><small>${detail}</small>${pref.glassStyle===id?`<span class="glass-check">${icon("check")}</span>`:""}</button>`).join("")}</div>
 <div class="glass-control"><div class="glass-control-top"><div><strong>Tingkat blur</strong><p>Seberapa buram lapisan kaca di seluruh website.</p></div><output id="glass-blur-value" for="glass-blur-slider">${off?0:pref.glassBlur} px</output></div><input id="glass-blur-slider" type="range" min="0" max="28" step="2" value="${pref.glassBlur}" ${off?"disabled":""} aria-label="Tingkat blur glassmorphism" aria-describedby="glass-blur-desc" style="--range-progress:${pref.glassBlur/28*100}%"><div class="glass-range-labels"><span>Jernih</span><span>Buram</span></div><p id="glass-blur-desc" class="glass-hint">${off?"Pilih Satin, Frost atau Crystal untuk mengatur blur.":"Disimpan otomatis untuk "+esc(welcomeName(user()))+"."}</p></div>
 <div class="glass-demo-scene" aria-label="Pratinjau material kaca secara langsung"><div class="glass-orbit"></div><div class="glass-demo-top"><span>LIVE PREVIEW <span class="glass-dot"></span></span><span>${esc(roleName(user().role).toUpperCase())} EDITION</span></div><div class="glass-demo-panel"><span>RUANG PRIBADI</span><h3>Ruang yang terasa <em>milikmu.</em></h3><div class="glass-demo-panel-foot"><span>${current.name} / <span id="glass-current-strength">${off?0:pref.glassBlur} px</span></span>${icon("sparkle-2")}</div></div><p class="glass-demo-caption">Contoh efek pada panel dan navigasi.</p></div>
 <p class="glass-a11y-note">${icon("info")}<span>Glassmorphism hanya digunakan pada permukaan pilihan. Nominal, QR, dan teks tetap tajam. Perangkat yang mengurangi transparansi mendapat tampilan lebih solid.</span></p>
 </section>`;
}
function settingsPage(){const dark=db.theme==='dark';return `${demoStrip()}${head('Pengaturan','Sesuaikan kenyamanan dan preferensimu.')}<div class="grid-main"><div class="stack"><div class="paper"><div class="eyebrow">TAMPILAN</div><div class="settings-item"><div><strong>Mode gelap</strong><div class="row-meta">Mode terang digunakan secara default.</div></div><button type="button" class="toggle ${dark?'on':''}" aria-label="Aktifkan mode gelap" aria-pressed="${dark}" data-action="toggle-theme"></button></div><div class="settings-item"><div><strong>Notifikasi pengingat</strong><div class="row-meta">Keterangan jatuh tempo di dalam website.</div></div><button type="button" class="toggle ${db.prefs.quiet?'on':''}" aria-label="Aktifkan notifikasi pengingat" aria-pressed="${db.prefs.quiet}" data-action="toggle-pref" data-key="quiet"></button></div></div>${glassStudio()}<div class="paper"><div class="eyebrow">KEAMANAN AKUN</div><div class="settings-item"><div><strong>Kata sandi</strong><div class="row-meta">Penggantian password asli belum tersedia dalam demo.</div></div><button class="btn btn-outline btn-small" data-action="password-info">Kelola</button></div><div class="settings-item"><div><strong>Privasi ranking</strong><div class="row-meta">Pengaturan ini disimpan pada perangkat demo.</div></div><button class="toggle ${user().anonymous?'on':''}" data-action="toggle-pref" data-key="anonymous" aria-pressed="${user().anonymous}" aria-label="Sembunyikan identitas publik"></button></div></div></div><aside class="stack"><div class="paper"><div class="eyebrow">SESI PRATINJAU</div><h3 style="margin:16px 0 7px">${esc(user().name)}</h3><p class="muted" style="font-size:12px">Kamu dapat mengganti peran untuk mencoba dashboard pengurus.</p><button class="btn btn-primary btn-block" style="margin-top:20px" data-action="switch-user">${icon('arrows')} Ganti akun demo</button><button class="btn btn-outline btn-block" style="margin-top:9px" data-action="reset-demo">${icon('history')} Atur ulang data demo</button></div></aside></div>`}
function helpPage(){const myTickets=db.tickets.filter(t=>t.userId===user().id);const faqs=[['Mengapa ada denda?','Aturan contoh menetapkan denda untuk setiap iuran bulanan yang melewati tanggal 15. Nilai final tetap perlu disahkan pengurus.'],['Apakah QR ini bisa digunakan membayar?','Belum. QR yang ada dalam prototipe merupakan ilustrasi. Pembayaran asli membutuhkan QR merchant resmi dan sumber status pembayaran yang sah.'],['Kapan status berubah menjadi lunas?','Dalam demo setelah bendahara menyetujui simulasi. Pada produksi, status harus berasal dari bukti penerimaan dana yang dapat dipertanggungjawabkan.'],['Bagaimana jika data saya tidak sesuai?','Buat tiket laporan masalah. Bendahara dapat meninjau dan mengajukan koreksi dengan alasan.']];return `${demoStrip()}${head('Pusat bantuan','Kalau ada yang tidak sesuai, sampaikan di sini.')}<div class="grid-main"><div class="stack"><section>${labelRow('Pertanyaan yang sering muncul')}<div class="paper">${faqs.map(([q,a],i)=>`<details class="settings-item" style="display:block"><summary style="cursor:pointer;list-style:none;font-weight:700">${esc(q)} <span style="float:right">${icon('chevron-down')}</span></summary><p class="muted" style="font-size:12px;margin:12px 5px 2px">${esc(a)}</p></details>`).join('')}</div></section><section>${labelRow('Laporan saya')}<div class="paper">${myTickets.length?myTickets.map(t=>`<div class="list-row"><div><strong>${esc(t.title)}</strong><div class="row-meta">${esc(t.id)} · ${shortDate(t.createdAt)}</div></div>${badgeStatus(t.status)}</div>`).join(''):`<div class="empty">${icon('help')}<strong>Belum ada laporan</strong><p>Ketika kamu mengirim masalah, statusnya akan muncul di sini.</p></div>`}</div></section></div><aside><div class="paper"><div class="eyebrow">BUTUH PENINJAUAN?</div><h2 style="margin:13px 0">Ceritakan yang terjadi.</h2><p class="muted" style="font-size:12px">Misalnya nominal salah, denda tidak sesuai, atau pembayaran belum tercatat.</p><button class="btn btn-primary btn-block" style="margin-top:20px" data-action="new-ticket">${icon('plus')} Buat laporan</button></div></aside></div>`}
function staffStats(){const due=db.obligations.filter(o=>o.status==='due'&&o.month==='2026-10');return {due:due.length,review:db.intents.filter(t=>t.status==='pending').length,arrears:[...new Set(db.obligations.filter(o=>o.status==='due'&&o.month<'2026-10').map(o=>o.userId))].length,collected:db.payments.filter(p=>p.obligationIds.some(id=>db.obligations.find(o=>o.id===id)?.month==='2026-10')).reduce((a,x)=>a+x.amount,0)}}
function staffDashboard(){const st=staffStats();const reviews=db.intents.filter(x=>x.status==='pending');return `${demoStrip()}${head(isChair()?'Ruang kepemimpinan':'Ruang bendahara',isChair()?'Lihat gambaran kas dan persetujuan yang membutuhkan perhatian.':'Prioritaskan verifikasi dan pencatatan kas yang perlu diselesaikan.')}<div class="banner-dark"><div><div class="eyebrow" style="color:#b8d3c4">RUANG KERJA / OKTOBER 2026</div><h2>${isChair()?'Keputusan yang baik, dimulai dari data yang jernih.':'Setiap transaksi, diperiksa dengan teliti.'}</h2><p>${st.review} pengajuan menunggu peninjauan. Pembayaran hanya sah setelah bukti sesuai.</p></div><div style="display:grid;gap:7px"><a href="#${isChair()?'/pengurus/persetujuan':'/pengurus/verifikasi'}" class="btn">${isChair()?'Pusat persetujuan':'Buka antrean'} ${icon('arrow-right')}</a><button class="btn btn-outline btn-small" style="background:transparent;color:white;border-color:#67867d" data-action="propose-policy">Usulkan kebijakan</button></div></div><div style="height:25px"></div><div class="staff-focus"><article><span class="eyebrow">PERLU VERIFIKASI</span><div class="number">${st.review}</div><span class="sub">Pengajuan tertunda</span></article><article><span class="eyebrow">BELUM BAYAR</span><div class="number">${st.due}</div><span class="sub">Anggota bulan ini</span></article><article><span class="eyebrow">TUNGGAKAN LAMA</span><div class="number">${st.arrears}</div><span class="sub">Anggota terdampak</span></article></div><div class="grid-main section"><section>${labelRow('Antrean verifikasi','/pengurus/verifikasi','Lihat antrean')}<div class="paper">${reviews.length?reviews.slice(0,5).map(t=>{const u=db.users.find(x=>x.id===t.userId);return `<div class="list-row"><div class="row-main">${avatar(u)}<div><div class="row-title">${esc(u.name)}</div><div class="row-meta">${esc(t.id)} · ${shortDate(t.createdAt)}</div></div></div><div class="row-right"><div class="row-amount">${rp(t.amount)}</div><a class="link-arrow" href="#/pengurus/verifikasi/${t.id}">Periksa ${icon('chevron-right')}</a></div></div>`}).join(''):`<div class="empty">${icon('check-circle')}<strong>Antrean bersih</strong><p>Tidak ada pengajuan yang menunggu pemeriksaan.</p></div>`}</div></section><aside class="stack"><div class="paper"><span class="eyebrow">PENERIMAAN KAS OKTOBER</span><div class="metric-value" style="margin:18px 0">${rp(st.collected)}</div><p class="muted" style="font-size:12px">Angka dari transaksi simulasi yang sudah diverifikasi.</p><div class="divider"></div><div class="details-list"><div class="detail-line"><span class="muted">Anggota tercatat</span><strong>${db.users.filter(x=>x.active).length}</strong></div><div class="detail-line"><span class="muted">Perlu pengingat</span><strong>${st.due}</strong></div></div><a href="#/pengurus/laporan" class="link-arrow" style="margin-top:22px">Buka laporan ${icon('arrow-right')}</a></div><div class="editorial-note"><div class="eyebrow">PENGINGAT</div><p>Satu transaksi dicek baik-baik, satu kali tercatat.</p></div></aside></div>`}
function verifyQueue(){const arr=db.intents.slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));return `${demoStrip()}${head('Verifikasi pembayaran','Cocokkan pengajuan dengan penerimaan sebelum menyetujui.')}<div class="paper"><div class="float-top"><span class="eyebrow">DAFTAR PENGAJUAN</span><span class="pill warn">${arr.filter(x=>x.status==='pending').length} menunggu</span></div><div class="divider"></div>${arr.length?arr.map(t=>{const u=db.users.find(x=>x.id===t.userId);return `<div class="list-row"><div class="row-main">${avatar(u)}<div><div class="row-title">${esc(u.name)}</div><div class="row-meta">${esc(t.id)} · ${shortDate(t.createdAt)}</div></div></div><div class="row-right"><div class="row-amount">${rp(t.amount)}</div><div style="margin:5px 0">${badgeStatus(t.status)}</div><a class="link-arrow" href="#/pengurus/verifikasi/${encodeURIComponent(t.id)}">Tinjau ${icon('chevron-right')}</a></div></div>`}).join(''):`<div class="empty">${icon('check-circle')}<strong>Tidak ada pengajuan</strong><p>Pengajuan anggota akan muncul di sini.</p></div>`}</div>`}
function verifyDetail(id){const t=getIntent(id),u=t&&db.users.find(x=>x.id===t.userId);if(!t||!u)return errorPage('Pengajuan tidak ditemukan','Data transaksi tersebut tidak tersedia.','/pengurus/verifikasi');return `${demoStrip()}<a class="link-arrow" href="#/pengurus/verifikasi">${icon('arrow-left')} Kembali ke antrean</a><div style="height:20px"></div>${head('Periksa pembayaran','Pemeriksaan ini hanya simulasi, belum terkoneksi ke merchant.')}<div class="grid-main"><div class="stack"><div class="paper"><div class="float-top"><span class="eyebrow">PENGAJUAN ${esc(t.id)}</span>${badgeStatus(t.status)}</div><div style="font-size:37px;letter-spacing:-1.3px;margin:23px 0 3px">${rp(t.amount)}</div><p class="muted" style="font-size:12px">${shortDate(t.createdAt)} · Referensi ${esc(t.reference||'Belum ada')}</p><div class="divider"></div><div class="details-list"><div class="detail-line"><span class="muted">Nama anggota</span><strong>${esc(u.name)}</strong></div><div class="detail-line"><span class="muted">NIM</span><strong>${esc(u.nim)}</strong></div><div class="detail-line"><span class="muted">Periode yang dipilih</span><strong>${t.obligationIds.map(id=>monthLabel(db.obligations.find(x=>x.id===id)?.month||'2026-10')).join(', ')}</strong></div><div class="detail-line"><span class="muted">Keterangan</span><strong>Data simulasi</strong></div></div></div><div class="soft-note warning">${icon('alert')}<span>Di website produksi, persetujuan harus dibatasi berdasarkan bukti transaksi resmi merchant. Tombol di sini khusus latihan interaksi antarpengguna.</span></div></div><aside class="paper"><span class="eyebrow">PILIH KEPUTUSAN</span><h2 style="margin:13px 0 7px">${t.status==='pending'?'Periksa sebelum lanjut.':'Keputusan sudah dicatat.'}</h2><p class="muted" style="font-size:12px">${t.status==='pending'?'Dalam demo, setujui untuk melihat bagaimana riwayat dan dashboard anggota ikut berubah.':'Pengajuan ini sudah diproses pada penyimpanan contoh lokal.'}</p>${t.status==='pending'?`<button class="btn btn-primary btn-block" style="margin-top:18px" data-action="approve-payment" data-id="${esc(t.id)}">${icon('check')} Setujui simulasi</button><button class="btn btn-outline btn-block" style="margin-top:9px" data-action="reject-payment" data-id="${esc(t.id)}">Tolak pengajuan</button>`:`<a class="btn btn-outline btn-block" style="margin-top:22px" href="#/pengurus/verifikasi">Kembali ke daftar</a>`}</aside></div>`}
function membersPage(){const list=db.users;return `${demoStrip()}${head('Direktori anggota','Kelola informasi anggota secara tertib.',isChair()?`<button class="btn btn-primary" data-action="new-member">${icon('plus')} Tambah anggota</button>`:'')}<div class="paper"><div class="float-top"><span class="eyebrow">${list.length} AKUN DATA CONTOH</span><button class="btn btn-outline btn-small" data-action="export-members">${icon('download')} Ekspor CSV</button></div><div style="height:17px"></div><div class="searchbar"><span class="icon">${icon('search')}</span><input class="input" id="member-search" placeholder="Cari nama atau NIM" aria-label="Cari anggota" data-action-input="member-search"/></div><div id="member-results" style="margin-top:17px">${memberRows(list)}</div></div>`}
function memberRows(list){return list.length?list.map(u=>`<a class="list-row" href="#/pengurus/anggota/${u.id}"><div class="row-main">${avatar(u)}<div><div class="row-title">${esc(u.name)}</div><div class="row-meta">${esc(u.nim)} · ${esc(u.year)}</div></div></div><div class="row-right"><div class="row-amount">${rp(totalDue(u.id))}</div>${u.active?`<span class="pill success">Aktif</span>`:'<span class="pill neutral">Nonaktif</span>'}</div></a>`).join(''):`<div class="empty">${icon('search')}<strong>Tidak ada hasil</strong><p>Coba nama atau NIM lain.</p></div>`}
function memberFinance(id){const u=db.users.find(x=>x.id===id);if(!u)return errorPage('Anggota tidak ditemukan','Data anggota tidak tersedia.','/pengurus/anggota');const o=db.obligations.filter(x=>x.userId===id).sort((a,b)=>b.month.localeCompare(a.month));return `${demoStrip()}<a href="#/pengurus/anggota" class="link-arrow">${icon('arrow-left')} Kembali ke direktori</a><div style="height:20px"></div>${head(u.name,`NIM ${u.nim} · Angkatan ${u.year}`)}<div class="grid-main"><div class="paper"><div class="float-top"><span class="eyebrow">RINCIAN BULANAN</span>${u.active?'<span class="pill success">Aktif</span>':'<span class="pill neutral">Nonaktif</span>'}</div><div class="divider"></div>${o.map(x=>`<div class="list-row"><div><div class="row-title">${monthLabel(x.month)}</div><div class="row-meta">Iuran ${rp(x.base)}${x.fine?' · Denda '+rp(x.fine):''}</div></div><div class="row-right"><div class="row-amount">${rp(x.base+x.fine)}</div>${badgeStatus(owingStatus(x))}</div></div>`).join('')}</div><aside class="stack"><div class="paper"><span class="eyebrow">KEWAJIBAN TERBUKA</span><div class="metric-value" style="margin:15px 0 8px">${rp(totalDue(id))}</div><p class="muted" style="font-size:12px">${owes(id).length} bulan belum selesai.</p><div class="divider"></div><button class="btn btn-outline btn-block" data-action="template-wa" data-id="${id}">${icon('send')} Buat pengingat</button>${isChair()?`<button class="btn btn-outline btn-block" style="margin-top:9px" data-action="toggle-member" data-id="${id}">${icon('users')} ${u.active?'Tandai nonaktif':'Aktifkan kembali'}</button>`:''}</div></aside></div>`}
function arrearsPage(){const list=db.users.map(u=>({u,open:owes(u.id),total:totalDue(u.id)})).filter(x=>x.total>0).sort((a,b)=>b.total-a.total);return `${demoStrip()}${head('Manajemen tunggakan','Ketahui prioritas, lalu hubungi anggota secara pribadi.')}<div class="staff-focus" style="margin-bottom:23px"><article><span class="eyebrow">ANGGOTA MENUNGGAK</span><div class="number">${list.length}</div><span class="sub">Dari ${db.users.length} anggota contoh</span></article><article><span class="eyebrow">TOTAL PIUTANG</span><div class="number" style="font-size:23px">${rp(list.reduce((a,x)=>a+x.total,0))}</div><span class="sub">Kas dan denda contoh</span></article><article><span class="eyebrow">PERIODE AKTIF</span><div class="number">Okt</div><span class="sub">2026</span></article></div><div class="paper"><div class="eyebrow" style="margin-bottom:10px">URUTAN BERDASARKAN BESAR TUNGGAKAN</div>${list.map(x=>`<div class="list-row"><div class="row-main">${avatar(x.u)}<div><div class="row-title">${esc(x.u.name)}</div><div class="row-meta">${x.open.length} bulan terbuka · ${esc(x.u.year)}</div></div></div><div class="row-right"><div class="row-amount">${rp(x.total)}</div><button class="btn btn-text btn-small" data-action="template-wa" data-id="${x.u.id}">Ingatkan ${icon('arrow-right')}</button></div></div>`).join('')}</div>`}
function greeting(){const h=Number(new Intl.DateTimeFormat('en-GB',{hour:'2-digit',hourCycle:'h23',timeZone:'Asia/Jakarta'}).format(new Date()));return h<11&&h>=5?'pagi':h<15&&h>=11?'siang':h<18&&h>=15?'sore':'malam'}
function waTemplate(id){const u=db.users.find(x=>x.id===id)||user(),list=owes(u.id);return `Selamat ${greeting()}, ${u.name}.\n\nMohon izin mengingatkan kas himpunan yang masih tercatat belum lunas.\n\nPeriode: ${list.map(o=>monthLabel(o.month)).join(', ')||'Tidak ada tunggakan'}\nIuran pokok: ${rp(list.reduce((a,x)=>a+x.base,0))}\nDenda tercatat: ${rp(list.reduce((a,x)=>a+x.fine,0))}\nTotal: ${rp(totalDue(u.id))}\n\nSilakan cek rincian di KasHima. Jika sudah membayar, mohon periksa status atau hubungi bendahara.\n\nTerima kasih.`}
function reminderPage(){const list=db.users.filter(u=>totalDue(u.id)>0);return `${demoStrip()}${head('Pusat reminder','Pesan yang sopan, sesuai tunggakan dan waktu.')}<div class="grid-main"><div class="paper"><div class="eyebrow">PILIH PENERIMA</div><div class="divider"></div>${list.map(u=>`<div class="list-row"><div class="row-main">${avatar(u)}<div><div class="row-title">${esc(u.name)}</div><div class="row-meta">${owes(u.id).length} bulan · ${rp(totalDue(u.id))}</div></div></div><div class="row-right"><button class="btn btn-outline btn-small" data-action="template-wa" data-id="${u.id}">Buat pesan ${icon('arrow-right')}</button></div></div>`).join('')}</div><aside class="stack"><div class="paper"><span class="eyebrow">MEKANISME PENGINGAT</span><h2 style="font-size:22px;margin:13px 0">Manusiawi dan tepat.</h2><p class="muted" style="font-size:12px">Kata pembuka mengikuti waktu Jakarta. Rincian bulan dan denda dihitung otomatis dari data contoh.</p><div class="divider"></div><p style="font-size:12px">Pukul 05.00–10.59 · Pagi</p><p style="font-size:12px">Pukul 11.00–14.59 · Siang</p><p style="font-size:12px">Pukul 15.00–17.59 · Sore</p><p style="font-size:12px">Pukul 18.00–21.00 · Malam</p></div><div class="soft-note">${icon('info')}<span>Membuka WhatsApp tidak membuktikan pesan terkirim atau sudah dibaca. KasHima tidak menggunakan API WhatsApp berbayar.</span></div></aside></div>`}
function ledgerRecords(){return [...db.payments.filter(p=>p.status==='verified').map(p=>({id:p.id,title:'Iuran '+p.obligationIds.map(id=>db.obligations.find(o=>o.id===id)?.month).filter(Boolean).map(monthLabel).join(', '),person:db.users.find(u=>u.id===p.userId)?.name||'Anggota',amount:p.amount,date:p.verifiedAt,kind:'income'})),...db.expenses.filter(x=>x.status==='approved').map(x=>({id:x.id,title:x.title,person:'Pengeluaran',amount:-x.amount,date:x.date+'T00:00:00+07:00',kind:'expense'}))].sort((a,b)=>new Date(b.date)-new Date(a.date))}
function ledgerPage(){const records=ledgerRecords(),income=records.filter(x=>x.amount>0).reduce((a,x)=>a+x.amount,0),out=records.filter(x=>x.amount<0).reduce((a,x)=>a-x.amount,0);return `${demoStrip()}${head('Buku kas','Setiap pencatatan memiliki asal dan arah uang.',`<button class="btn btn-primary" data-action="new-expense">${icon('plus')} Usulkan pengeluaran</button>`)}<div class="staff-focus" style="margin-bottom:24px"><article><span class="eyebrow">UANG MASUK</span><div class="number" style="font-size:23px">${rp(income)}</div><span class="sub">Transaksi simulasi</span></article><article><span class="eyebrow">PENGELUARAN</span><div class="number" style="font-size:23px">${rp(out)}</div><span class="sub">Diklaim disetujui dalam demo</span></article><article><span class="eyebrow">SELISIH BUKU</span><div class="number" style="font-size:23px">${rp(income-out)}</div><span class="sub">Bukan saldo bank sebenarnya</span></article></div><div class="paper"><div class="float-top"><span class="eyebrow">TRANSAKSI TERCATAT</span><button class="btn btn-outline btn-small" data-action="export-ledger">${icon('download')} Ekspor CSV</button></div><div class="divider"></div>${records.slice(0,35).map(x=>`<div class="list-row"><div class="row-main"><span class="row-icon">${icon(x.kind==='income'?'arrow-right':'receipt')}</span><div><div class="row-title">${esc(x.title)}</div><div class="row-meta">${esc(x.person)} · ${shortDate(x.date)}</div></div></div><div class="row-right"><div class="row-amount" style="color:${x.amount>0?'var(--success)':'var(--ink)'}">${x.amount>0?'+':'−'}${rp(Math.abs(x.amount))}</div><div class="row-meta">${esc(x.id)}</div></div></div>`).join('')}</div>`}
function chartIncome(){let vals=Array.from({length:10},(_,i)=>db.payments.filter(p=>p.obligationIds.some(id=>db.obligations.find(x=>x.id===id)?.month===`2026-${String(i+1).padStart(2,'0')}`)).reduce((a,p)=>a+p.amount,0));let max=Math.max(...vals,10000);return `<div class="chart-wrap" role="img" aria-label="Grafik ilustrasi penerimaan kas Januari hingga Oktober 2026">${vals.map((v,i)=>`<div class="chart-bar ${i===9?'current':''}" data-value="${rp(v)}" style="height:${Math.max(5,Math.round(v/max*175))}px"><span class="chart-label">${MONTHS[i].slice(0,3)}</span></div>`).join('')}</div>`}
function reportsPage(){const st=staffStats(),income=ledgerRecords().filter(x=>x.amount>0).reduce((a,x)=>a+x.amount,0);return `${demoStrip()}${head('Laporan keuangan','Ringkasan yang bisa ditelusuri kembali.',`<button class="btn btn-outline" data-action="export-ledger">${icon('download')} Unduh CSV</button>`)}<div class="grid-main"><div class="stack"><div class="paper"><div class="float-top"><span class="eyebrow">PENERIMAAN PER BULAN</span><span class="pill">Jan–Okt 2026</span></div><div style="margin-top:14px">${chartIncome()}</div><p class="muted" style="font-size:11px;margin:31px 0 0">Bar diturunkan dari data simulasi pembayaran dan berubah setelah ada konfirmasi demo.</p></div><div class="paper"><span class="eyebrow">RINCIAN KEWAJIBAN</span><div class="divider"></div><div class="details-list"><div class="detail-line"><span class="muted">Iuran pokok belum lunas</span><strong>${rp(db.obligations.filter(x=>x.status==='due').reduce((a,x)=>a+x.base,0))}</strong></div><div class="detail-line"><span class="muted">Denda belum lunas</span><strong>${rp(db.obligations.filter(x=>x.status==='due').reduce((a,x)=>a+x.fine,0))}</strong></div><div class="detail-line"><span class="muted">Total penerimaan tervalidasi demo</span><strong>${rp(income)}</strong></div></div></div></div><aside class="stack"><div class="paper"><span class="eyebrow">ANGKA UTAMA</span><div class="metric-value" style="margin:20px 0 7px">${rp(st.collected)}</div><p class="muted" style="font-size:12px">Penerimaan bulan Oktober 2026.</p><div class="divider"></div><div class="detail-line"><span class="muted">Anggota aktif</span><strong>${db.users.filter(x=>x.active).length}</strong></div><div class="detail-line" style="margin-top:15px"><span class="muted">Antrean verifikasi</span><strong>${st.review}</strong></div></div><div class="soft-note warning">${icon('alert')}<span>Laporan ini tidak tersambung ke rekening bank dan hanya mencerminkan data browser. Rekonsiliasi merchant asli wajib sebelum menjadi LPJ resmi.</span></div></aside></div>`}
function disputesPage(){const list=db.tickets;return `${demoStrip()}${head('Sengketa dan koreksi','Satu laporan, satu jejak penanganan.')}<div class="paper"><div class="float-top"><span class="eyebrow">DAFTAR TIKET</span><span class="pill">${list.length} laporan</span></div><div class="divider"></div>${list.length?list.map(t=>`<div class="list-row"><div><div class="row-title">${esc(t.title)}</div><div class="row-meta">${esc(db.users.find(u=>u.id===t.userId)?.name||'-')} · ${shortDate(t.createdAt)}</div><div class="row-meta">${esc(t.description)}</div></div><div class="row-right">${badgeStatus(t.status)}<button class="btn btn-text btn-small" data-action="resolve-ticket" data-id="${esc(t.id)}" ${t.status==='closed'?'disabled':''}>Selesaikan</button></div></div>`).join(''):`<div class="empty">${icon('check-circle')}<strong>Belum ada sengketa</strong><p>Laporan anggota akan masuk antrean ini.</p></div>`}</div>`}
function approvalsPage(){const list=db.proposals;return `${demoStrip()}${head('Pusat persetujuan','Keputusan keuangan tidak boleh sepihak.')}<div class="grid-main"><div class="paper"><div class="float-top"><span class="eyebrow">MENUNGGU KEPUTUSAN</span><span class="pill warn">${list.filter(x=>x.status==='submitted').length} usulan</span></div><div class="divider"></div>${list.length?list.map(p=>`<div class="list-row"><div><div class="row-title">${p.kind==='expense'?'Pengeluaran':'Perubahan kebijakan'}: ${esc(p.title)}</div><div class="row-meta">${p.kind==='expense'?rp(p.amount):esc(p.description||'')} · ${shortDate(p.date)}</div><div class="row-meta">Pengusul: ${esc(db.users.find(x=>x.id===p.by)?.name||'-')}</div></div><div class="row-right">${badgeStatus(p.status)}${p.status==='submitted'?`<button class="btn btn-text btn-small" data-action="approve-proposal" data-id="${p.id}">Tinjau ${icon('arrow-right')}</button>`:''}</div></div>`).join(''):`<div class="empty">${icon('check-circle')}<strong>Belum ada usulan</strong><p>Pengeluaran dan permintaan perubahan akan muncul di sini.</p></div>`}</div><aside class="stack"><div class="paper"><span class="eyebrow">DUAL CONTROL</span><h2 class="serif" style="font-size:29px;margin:14px 0 8px">Satu pengusul. Satu pemeriksa.</h2><p class="muted" style="font-size:12px">Perubahan keuangan sensitif harus mempunyai alasan, pemberi persetujuan yang berbeda, dan jejak audit.</p></div></aside></div>`}
function periodsPage(){return `${demoStrip()}${head('Periode kepengurusan','Riwayat tidak berhenti ketika pengurus berganti.')}<div class="grid-main"><div class="paper"><div class="eyebrow">PERIODE HIMPUNAN</div><div class="divider"></div><div class="log-list"><div class="log-entry"><div class="log-time">1 Juli 2026 – 30 Juni 2027</div><div class="log-title">Kepengurusan 2026/2027 <span class="pill success">Aktif</span></div><div class="log-desc">Seluruh pembayaran contoh berada pada masa ini.</div></div><div class="log-entry"><div class="log-time">Periode berikutnya</div><div class="log-title">Belum dijadwalkan</div><div class="log-desc">Perubahan hak akses memerlukan serah terima resmi.</div></div></div></div><aside class="paper"><div class="eyebrow">SISTEM BERKELANJUTAN</div><h2 style="margin:14px 0">Pergantian lebih tertib.</h2><p class="muted" style="font-size:12px">Sebelum periode baru dibuka, bendahara menutup dan merekonsiliasi pembukuan. Admin lama kemudian menyerahkan akses secara tercatat.</p><button class="btn btn-outline btn-block" data-action="handover-info" style="margin-top:19px">${icon('file')} Lihat prosedur serah terima</button></aside></div>`}
function membershipPage(){return `${demoStrip()}${head('Administrasi anggota','Import dan perubahan status perlu pemeriksaan.',`<button class="btn btn-primary" data-action="new-member">${icon('plus')} Tambah anggota</button>`)}<div class="grid-main"><div class="paper"><div class="float-top"><span class="eyebrow">${db.users.length} ANGGOTA TERDAFTAR</span><button class="btn btn-outline btn-small" data-action="import-csv">${icon('upload')} Impor CSV contoh</button></div><div class="divider"></div>${memberRows(db.users)}</div><aside class="paper"><div class="eyebrow">VALIDASI IMPORT</div><h2 style="font-size:22px;margin:14px 0">Data masuk, diperiksa dulu.</h2><p class="muted" style="font-size:12px">Nama dan NIM harus sesuai. Data duplikat, baris kosong, dan nominal historis yang ambigu tidak boleh langsung masuk tagihan.</p><div class="divider"></div><p class="label-small">Format kolom contoh</p><code style="display:block;padding:14px;background:var(--tint);border-radius:10px;font-size:11px;overflow:auto">nim,nama,angkatan</code></aside></div>`}
function policyPage(){return `${demoStrip()}${head('Kebijakan kas','Aturan terdokumentasi, tidak berubah diam-diam.')}<div class="grid-main"><div class="paper"><div class="eyebrow">KONFIGURASI SAAT INI (SIMULASI)</div><div style="height:16px"></div><div class="details-list"><div class="detail-line"><span class="muted">Iuran bulanan</span><strong>Rp10.000</strong></div><div class="divider" style="margin:5px 0"></div><div class="detail-line"><span class="muted">Batas pembayaran</span><strong>Tanggal 15</strong></div><div class="divider" style="margin:5px 0"></div><div class="detail-line"><span class="muted">Denda per bulan terlambat</span><strong>Rp60.000</strong></div><div class="divider" style="margin:5px 0"></div><div class="detail-line"><span class="muted">Zona waktu</span><strong>Asia/Jakarta (WIB)</strong></div></div><div class="soft-note warning" style="margin-top:25px">${icon('alert')}<span>Nominal denda masih harus disahkan pengurus karena sebelumnya pernah disebut Rp50.000. Dalam demo, tidak ada perubahan retroaktif.</span></div></div><aside class="paper"><div class="eyebrow">PERUBAHAN KEBIJAKAN</div><h2 style="margin:13px 0">Aturan baru harus disetujui.</h2><p class="muted" style="font-size:12px">Setiap kebijakan menyimpan tanggal mulai berlaku dan alasan. Tagihan lama tidak dihitung ulang otomatis.</p><button class="btn btn-outline btn-block" data-action="propose-policy" style="margin-top:22px">${icon('pencil')} Usulkan perubahan</button></aside></div>`}
function rolesPage(){const list=db.users;return `${demoStrip()}${head('Hak akses','Peran diberikan sesuai pekerjaan dan periode.')}<div class="paper"><div class="float-top"><span class="eyebrow">DAFTAR AKSES DEMO</span><span class="pill neutral">Pengaturan sensitif</span></div><div class="divider"></div>${list.map(u=>`<div class="list-row"><div class="row-main">${avatar(u)}<div><div class="row-title">${esc(u.name)}</div><div class="row-meta">${esc(u.nim)}</div></div></div><div class="row-right">${u.role==='chair'?'<span class="pill warn">Kahima</span>':u.role==='treasurer'?'<span class="pill success">Bendahara</span>':'<span class="pill neutral">Anggota</span>'}</div></div>`).join('')}</div><div class="soft-note" style="margin-top:20px">${icon('shield')}<span>Perubahan peran melalui persetujuan resmi organisasi dan audit. Pada pratinjau ini, penggantian pengguna demo tidak mengubah hak akses sungguhan.</span></div>`}
function auditPage(){return `${demoStrip()}${head('Audit & operasi','Jejak peristiwa penting tanpa perubahan diam-diam.')}<div class="grid-main"><div class="paper"><div class="eyebrow">LOG AKTIVITAS SIMULASI</div><div class="divider"></div><div class="log-list">${db.audit.map(x=>`<div class="log-entry"><div class="log-time">${shortDate(x.date)} · ${shortTime(x.date)}</div><div class="log-title">${esc(x.text)}</div><div class="log-desc">Aktor: ${esc(x.by)}</div></div>`).join('')}</div></div><aside class="stack"><div class="paper"><div class="eyebrow">STATUS PROTOTIPE</div><h2 style="font-size:21px;margin:15px 0">Berjalan lokal.</h2><div class="details-list"><div class="detail-line"><span class="muted">Penyimpanan</span><strong>Browser lokal</strong></div><div class="detail-line"><span class="muted">Gateway QRIS</span><strong class="text-warning">Belum aktif</strong></div><div class="detail-line"><span class="muted">Koneksi database</span><strong>Belum ada</strong></div></div></div><div class="soft-note">${icon('info')}<span>Ini halaman pratinjau. Peluncuran produksi masih membutuhkan server, autentikasi, database, backup, serta sumber verifikasi pembayaran yang sah.</span></div></aside></div>`}
function errorPage(title,msg,back='/app'){return `${demoStrip()}<div class="empty" style="min-height:340px;align-content:center">${icon('help')}<h2 style="margin:0">${esc(title)}</h2><p>${esc(msg)}</p><a class="btn btn-primary" href="#${back}">Kembali ${icon('arrow-right')}</a></div>`}
function authPage(r){const isLogin=r==='/login',activate=r==='/aktivasi',forgot=r==='/lupa-password';const title=isLogin?'Selamat datang kembali.':activate?'Aktifkan akunmu.':forgot?'Pulihkan aksesmu.':'Buat kata sandi baru.';const desc=isLogin?'Masuk menggunakan NIM yang didaftarkan oleh pengurus.':activate?'Di sistem produksi, kredensial awal wajib diganti saat login pertama.':forgot?'Pemulihan akun asli memerlukan identitas dan kanal terverifikasi.':'Kata sandi perlu disimpan secara aman di server.';return `<div class="auth-shell"><aside class="auth-art"><div class="brand"><span class="brand-mark">k.</span><span><span class="brand-word">KasHima</span><span class="brand-caption">Ruang keuangan</span></span></div><div><div class="eyebrow" style="color:#c8d8ca">RUANG KEUANGAN HIMPUNAN</div><h1>Lebih tertib,<br/><em>lebih tenang.</em></h1><p class="footnote">Dari iuran bulanan hingga laporan keuangan. Seluruhnya berada di satu ruang yang jelas.</p></div><div class="footnote">KasHima · Pengalaman mobile-first, dirancang untuk kebutuhan himpunan.</div></aside><div class="auth-form-wrap"><section class="auth-form"><div class="eyebrow">AKSES PRATINJAU</div><h2>${title}</h2><p class="intro">${desc}</p>${isLogin?`<form id="login-form" class="form-stack"><div class="field"><label for="login-nim">Nomor Induk Mahasiswa</label><input id="login-nim" class="input" name="nim" inputmode="numeric" required placeholder="Contoh: 240000001" value="240000001"></div><div class="field"><label for="login-pass">Kata sandi (simulasi)</label><input id="login-pass" class="input" name="password" type="password" required placeholder="Masukkan kata sandi" value="demo"></div><button class="btn btn-primary btn-block" type="submit">Masuk pratinjau ${icon('arrow-right')}</button></form><div class="auth-demo-notice">Ini demo lokal. Gunakan NIM contoh 240000001 dan password bebas. Tidak ada autentikasi sungguhan atau database.</div><div style="display:flex;justify-content:space-between"><a class="link-arrow" href="#/lupa-password">Lupa password?</a><button class="btn btn-text btn-small" data-action="switch-user">Pilih akun demo</button></div>`:`<div class="soft-note">${icon('shield')}<span>Alur ${activate?'aktivasi':'pemulihan'} produksi harus terhubung ke server, token sekali pakai, dan verifikasi identitas. Prototipe tidak menyimpan password.</span></div><div class="mini-stack" style="margin-top:23px"><a class="btn btn-primary btn-block" href="#/login">Kembali ke login ${icon('arrow-right')}</a></div>`}<div class="auth-footer">KasHima · Data simulasi, tidak memproses uang.</div></section></div></div>`}
const viewRoutes={
 '/app':pageHome,'/app/tagihan':pageDue,'/app/riwayat':historyPage,'/app/leaderboard':leaderboardPage,'/app/notifikasi':notifPage,'/app/profil':profilePage,'/app/pengaturan':settingsPage,'/app/bantuan':helpPage,
 '/pengurus/keuangan':staffDashboard,'/pengurus/verifikasi':verifyQueue,'/pengurus/anggota':membersPage,'/pengurus/tunggakan':arrearsPage,'/pengurus/reminder':reminderPage,'/pengurus/buku-kas':ledgerPage,'/pengurus/laporan':reportsPage,'/pengurus/sengketa':disputesPage,
 '/pengurus/persetujuan':approvalsPage,'/pengurus/periode':periodsPage,'/pengurus/keanggotaan':membershipPage,'/pengurus/kebijakan':policyPage,'/pengurus/akses':rolesPage,'/pengurus/audit':auditPage
};
function viewFor(r){if(viewRoutes[r])return viewRoutes[r]();let m;if((m=r.match(/^\/app\/bayar\/([^/]+)\/berhasil$/)))return pageSuccess(m[1]);if((m=r.match(/^\/app\/bayar\/([^/]+)\/menunggu$/)))return pagePending(m[1]);if((m=r.match(/^\/app\/bayar\/([^/]+)$/)))return paymentPage(m[1]);if((m=r.match(/^\/app\/riwayat\/([^/]+)$/)))return paymentDetail(m[1]);if((m=r.match(/^\/pengurus\/verifikasi\/([^/]+)$/)))return verifyDetail(m[1]);if((m=r.match(/^\/pengurus\/anggota\/([^/]+)$/)))return memberFinance(m[1]);return errorPage('Halaman belum ditemukan','Periksa alamat atau kembali ke beranda.')}
function render(scroll=true){applyGlass();let r=route(),root=document.getElementById('app');if(!root)return;let auth=['/login','/aktivasi','/lupa-password','/reset-password'].includes(r);if(!db.sessionActive&&!auth){location.hash='#/login';r='/login';auth=true}document.title=`${auth||r==='/login'?'Masuk':([...navMember,...navStaff,...navChair].find(x=>x[1]===r)?.[0]||'KasHima')} · KasHima`;
 if(auth){root.innerHTML=authPage(r)}else if(r.startsWith('/pengurus/')&&!hasStaff()){root.innerHTML=`<div class="app-shell role-${user().role}"><button class="skip-link" data-action="skip-content">Lewati ke konten</button>${sidebar(r)}<div class="main-wrap">${topbar(r)}${headerMobile()}<main class="page">${errorPage('Akses terbatas','Halaman ini hanya tersedia untuk akun pengurus dalam pratinjau.','/app')}</main>${mobileNav(r)}</div></div>`}else if(r.startsWith('/pengurus/persetujuan')&&!isChair()||r.startsWith('/pengurus/periode')&&!isChair()||r.startsWith('/pengurus/kebijakan')&&!isChair()||r.startsWith('/pengurus/akses')&&!isChair()||r.startsWith('/pengurus/keanggotaan')&&!isChair()||r.startsWith('/pengurus/audit')&&!isChair()){root.innerHTML=`<div class="app-shell role-${user().role}"><button class="skip-link" data-action="skip-content">Lewati ke konten</button>${sidebar(r)}<div class="main-wrap">${topbar(r)}${headerMobile()}<main class="page">${errorPage('Butuh wewenang Kahima','Ganti ke akun Kahima untuk mencoba halaman ini.','/pengurus/keuangan')}</main>${mobileNav(r)}</div></div>`}
 else{root.innerHTML=`<div class="app-shell role-${user().role}"><button class="skip-link" data-action="skip-content">Lewati ke konten</button>${sidebar(r)}<div class="main-wrap">${topbar(r)}${headerMobile()}<main class="page" id="main-content" tabindex="-1">${viewFor(r)}</main>${mobileNav(r)}</div></div>`}
 if(scroll)window.scrollTo({top:0,behavior:'instant'})
}
function go(p){if(location.hash===`#${p}`)render();else location.hash=`#${p}`}
let modalInvoker=null;
function modal(title,body,footer=''){modalInvoker=document.activeElement;const root=document.getElementById('modal-root');root.innerHTML=`<div class="modal-backdrop" id="overlay" role="presentation"><div role="dialog" aria-modal="true" aria-label="${esc(title)}" class="modal" tabindex="-1"><div class="modal-header"><h3>${esc(title)}</h3><button class="icon-button" data-action="close-modal" aria-label="Tutup dialog">${icon('plus')}</button></div>${body}${footer?`<div class="modal-actions">${footer}</div>`:''}</div></div>`;root.querySelector('.modal [type=submit],.modal input,.modal select,.modal textarea,.modal button:not([data-action=close-modal])')?.focus()||root.querySelector('.modal')?.focus()}
function closeModal(){const had=!!document.querySelector('#modal-root .modal');document.getElementById('modal-root').innerHTML='';if(had&&modalInvoker&&document.contains(modalInvoker))modalInvoker.focus();modalInvoker=null}
function editProfile(){const me=user();modal('Ubah identitas profil',`<p class="modal-intro">Gunakan nama yang ingin ditampilkan pada akun demo. NIM dan peran dikelola oleh pengurus.</p><form id="profile-form" class="form-stack"><div class="field"><label for="identity-fullname">Nama lengkap</label><input id="identity-fullname" class="input" name="name" required minlength="3" maxlength="70" autocomplete="name" value="${esc(me.name)}" placeholder="Nama sesuai data anggota"/><span class="helper-text">3–70 karakter. Ditampilkan pada profil dan data demo pengurus.</span></div><div class="field"><label for="identity-nickname">Nama panggilan</label><input id="identity-nickname" class="input" name="nickname" required minlength="2" maxlength="18" value="${esc(welcomeName(me))}" placeholder="Nama panggilan"/><span class="helper-text">Ditampilkan pada sapaan dan identitas ringkas.</span></div><div class="modal-form-actions"><button class="btn btn-outline" type="button" data-action="close-modal">Batal</button><button class="btn btn-primary" type="submit">Simpan perubahan ${icon('check')}</button></div></form>`)}
function logoutModal(){modal('Keluar dari KasHima?',`<p class="modal-intro">Sesi pratinjau untuk <strong>${esc(user().name)}</strong> akan ditutup. Data contoh dan foto profilmu tetap tersimpan di browser ini.</p><div class="soft-note">${icon('info')}<span>Ini hanya demo. Sistem akun produksi belum menggunakan autentikasi sungguhan.</span></div>`,`<button class="btn btn-outline" data-action="close-modal">Tetap di sini</button><button class="btn btn-primary" data-action="confirm-logout">Ya, keluar ${icon('logout')}</button>`)}
function userSwitcher(){modal('Ganti akun pratinjau',`<p class="muted" style="font-size:12px;margin-bottom:18px">Pilih peran untuk mencoba alur anggota, bendahara, atau Kahima. Ini hanya pergantian identitas pada data contoh.</p><div class="option-grid">${[['u1','Anggota'],['u5','Bendahara'],['u6','Kahima']].map(([id,role])=>{const actor=db.users.find(x=>x.id===id);return `<button class="option" data-action="choose-user" data-id="${id}">${avatar(actor)}<span style="flex:1"><strong>${esc(actor.name)}</strong><br/><span class="option-desc">${role} · Pratinjau</span></span>${icon('arrow-right')}</button>`}).join('')}</div>`)}
function csvDownload(filename,header,rows){const csv=[header,...rows].map(a=>a.map(v=>{const s=String(v??'');const safe=/^[=+\-@\t\r]/.test(s)?`'${s}`:s;return '"'+safe.replace(/"/g,'""')+'"'}).join(',')).join('\r\n');const blob=new Blob(['\ufeff',csv],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Berkas CSV pratinjau disimpan.')}
function submitPayment(id){const t=getIntent(id);if(!t||t.userId!==user().id){toast('Transaksi tidak tersedia untuk akun ini.');return}if(!['created','rejected'].includes(t.status)){go(`/app/bayar/${id}/menunggu`);return}t.status='pending';t.reference=`SIM-${Date.now().toString().slice(-7)}`;t.createdAt=new Date().toISOString();audit(`Anggota membuat pengajuan pembayaran demo ${t.id}`);save();go(`/app/bayar/${id}/menunggu`);toast('Pengajuan simulasi berhasil dicatat.')}
function approvePayment(id){const t=getIntent(id);if(!hasStaff()||!t||t.status!=='pending'){toast('Pengajuan sudah diproses atau tidak tersedia.');return}if(t.userId===user().id){toast('Pengurus tidak dapat menyetujui pembayaran sendiri.');return}modal('Setujui simulasi pembayaran',`<div class="soft-note warning">${icon('alert')}<span>Ini hanya menyetujui data contoh di browser. Tidak ada uang masuk atau pengecekan rekening bank.</span></div><p style="margin:17px 0 0">Konfirmasi <strong>${rp(t.amount)}</strong> untuk ${esc(db.users.find(u=>u.id===t.userId)?.name||'anggota')}?</p>`,`<button class="btn btn-outline" data-action="close-modal">Batal</button><button class="btn btn-primary" data-action="confirm-approve" data-id="${t.id}">Setujui data demo</button>`)}
function confirmApprove(id){const t=getIntent(id);if(!hasStaff()||!t||t.status!=='pending'||t.userId===user().id){closeModal();toast('Tidak dapat memverifikasi transaksi ini.');return}if(db.payments.some(x=>x.intentId===id)){closeModal();toast('Transaksi sudah pernah dicatat.');return}t.status='verified';t.verifiedAt=new Date().toISOString();t.obligationIds.forEach(oid=>{const o=db.obligations.find(x=>x.id===oid);if(o&&o.status==='due')o.status='paid'});const payment={id:uid('KAS-DEMO').toUpperCase(),intentId:id,userId:t.userId,obligationIds:[...t.obligationIds],amount:t.amount,paidAt:t.createdAt,verifiedAt:t.verifiedAt,status:'verified',method:'Simulasi verifikasi bendahara',reference:t.reference||'SIMULASI'};db.payments.unshift(payment);db.notifications.unshift({id:uid('notif'),userId:t.userId,title:'Pembayaran demo disetujui',body:`Kas ${rp(t.amount)} sudah tercatat pada simulasi KasHima.`,read:false,date:new Date().toISOString()});audit(`Bendahara menyetujui pembayaran simulasi ${id}`);closeModal();save();render();toast('Simulasi pembayaran tercatat lunas.');}
function rejectPayment(id){const t=getIntent(id);if(!hasStaff()||!t||t.status!=='pending')return;modal('Tolak pengajuan',`<p class="muted" style="font-size:12px">Penolakan dalam demo tidak mengubah kewajiban kas.</p><form id="reject-form" class="form-stack"><input type="hidden" name="id" value="${t.id}"><div class="field"><label for="reject-reason">Alasan</label><textarea required minlength="5" class="textarea" name="reason" id="reject-reason" placeholder="Contoh: informasi pembayaran belum dapat dicocokkan"></textarea></div><button class="btn btn-primary btn-block" type="submit">Tolak pengajuan</button></form>`)}
function showWa(id){const u=db.users.find(x=>x.id===id);if(!u)return;const msg=waTemplate(id);modal(`Reminder untuk ${u.name}`,`<div class="field"><label>Pratinjau pesan pribadi</label><textarea id="wa-preview" class="textarea" style="min-height:270px" readonly>${esc(msg)}</textarea></div><div class="soft-note" style="margin-top:13px">${icon('info')}<span>Kontak pada data demo bukan nomor sungguhan. Mengklik salin tidak berarti pesan sudah terkirim.</span></div>`,`<button class="btn btn-outline" data-action="copy-wa" data-id="${id}">${icon('copy')} Salin pesan</button><button class="btn btn-primary" data-action="open-wa" data-id="${id}">${icon('external-link')} Buka WhatsApp</button>`)}
function expenseProposal(){modal('Usulkan pengeluaran',`<p class="muted" style="font-size:12px">Usulan demo masuk ke halaman persetujuan Kahima.</p><form id="expense-form" class="form-stack"><div class="field"><label for="expense-title">Keperluan</label><input class="input" id="expense-title" name="title" required maxlength="100" placeholder="Contoh: Konsumsi rapat"></div><div class="field"><label for="expense-amount">Nominal (rupiah)</label><input class="input" id="expense-amount" name="amount" inputmode="numeric" type="number" min="1000" step="1000" required placeholder="150000"></div><button type="submit" class="btn btn-primary btn-block">Ajukan persetujuan</button></form>`)}
function newTicket(){modal('Buat laporan masalah',`<form id="ticket-form" class="form-stack"><div class="field"><label for="ticket-title">Jenis masalah</label><select name="title" id="ticket-title" class="select"><option>Pembayaran belum tercatat</option><option>Denda tidak sesuai</option><option>Nominal tagihan salah</option><option>Lainnya</option></select></div><div class="field"><label for="ticket-desc">Jelaskan masalahmu</label><textarea id="ticket-desc" name="description" required minlength="12" maxlength="700" class="textarea" placeholder="Tulis periode dan informasi pendukung. Jangan bagikan password."></textarea></div><button type="submit" class="btn btn-primary btn-block">Kirim laporan ${icon('arrow-right')}</button></form>`)}
function newMember(){modal('Tambah anggota contoh',`<form id="member-form" class="form-stack"><div class="field"><label for="new-name">Nama lengkap</label><input class="input" id="new-name" name="name" required minlength="3" maxlength="70"></div><div class="field"><label for="new-nim">NIM</label><input class="input" id="new-nim" name="nim" required inputmode="numeric" pattern="[0-9]{6,20}" title="6 sampai 20 digit"></div><div class="field"><label for="new-year">Angkatan</label><select class="select" id="new-year" name="year"><option>2026</option><option>2025</option><option selected>2024</option><option>2023</option><option>2022</option></select></div><button type="submit" class="btn btn-primary btn-block">Tambah anggota demo</button></form>`)}
function proposePolicy(){modal('Usulkan kebijakan baru',`<form id="policy-form" class="form-stack"><div class="field"><label for="policy-title">Judul kebijakan</label><input class="input" id="policy-title" name="title" placeholder="Contoh: Perubahan iuran November" required maxlength="100"></div><div class="field"><label for="policy-desc">Alasan dan tanggal efektif</label><textarea class="textarea" id="policy-desc" name="description" required minlength="12" placeholder="Tuliskan kebijakan, alasan, dan kapan mulai berlaku"></textarea></div><div class="soft-note">${icon('info')}<span>Persetujuan contoh tidak mengubah tagihan lama. Mesin tarif produksi belum terhubung.</span></div><button type="submit" class="btn btn-primary btn-block">Kirim usulan</button></form>`)}
function approveProposal(id){const pr=db.proposals.find(x=>x.id===id);if(!isChair()||!pr||pr.status!=='submitted'){toast('Hanya Kahima dapat meninjau usulan belum diproses.');return}if(pr.by===user().id){toast('Pengusul tidak dapat menyetujui sendiri.');return}modal('Setujui usulan',`<p>${esc(pr.title)}</p><p class="muted" style="font-size:12px">Tindakan ini hanya mengubah data pratinjau. Tidak melakukan transfer uang atau mengubah kebijakan produksi.</p>`,`<button class="btn btn-outline" data-action="close-modal">Batal</button><button class="btn btn-primary" data-action="confirm-proposal" data-id="${id}">Setujui demo</button>`)}
function routeKey(k){return paths[k]||'/app'}
function showRoleMenu(){userSwitcher()}
function infoModal(title,msg){modal(title,`<p class="muted" style="font-size:13px;margin:0">${msg}</p>`,`<button class="btn btn-primary" data-action="close-modal">Mengerti</button>`)}
function copyText(s){if(navigator.clipboard&&location.protocol!=='file:')navigator.clipboard.writeText(s).then(()=>toast('Teks disalin.')).catch(()=>fallbackCopy(s));else fallbackCopy(s)}
function fallbackCopy(s){const el=document.createElement('textarea');el.value=s;document.body.append(el);el.select();try{document.execCommand('copy');toast('Teks disalin.')}catch{toast('Salin manual dari pratinjau pesan.')}el.remove()}
function saveQR(id){const svg=qrSample(id).replace(/^<svg/,'<svg xmlns="http://www.w3.org/2000/svg"');const blob=new Blob([svg],{type:'image/svg+xml'});const a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download=`kashima-DEMO-bukan-qris-${id}.svg`;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Ilustrasi QR tersimpan. Bukan QRIS untuk bayar.')}
function initPay(){const due=owes();if(!due.length){toast('Semua kewajiban contoh sudah lunas.');return}const old=db.intents.find(t=>t.userId===user().id&&['created','pending'].includes(t.status)&&t.obligationIds.join(',')===due.map(o=>o.id).join(','));if(old){go(old.status==='pending'?`/app/bayar/${old.id}/menunggu`:`/app/bayar/${old.id}`);return}const intent={id:uid('PAY-DEMO').toUpperCase(),userId:user().id,obligationIds:due.map(o=>o.id),amount:totalDue(),createdAt:new Date().toISOString(),status:'created'};db.intents.push(intent);save();go(`/app/bayar/${intent.id}`)}
function selectUser(id){if(!db.users.find(u=>u.id===id)){toast('Akun demo tidak tersedia.');return}db.userId=id;db.sessionActive=true;save();closeModal();go(hasStaff()?'/pengurus/keuangan':'/app');render();toast(`Mode pratinjau: ${roleName(user().role)}`)}
document.addEventListener('click',e=>{if(e.target.id==='overlay'){closeModal();return}const a=e.target.closest('[data-action]');if(!a)return;const cmd=a.dataset.action,id=a.dataset.id;switch(cmd){
 case 'skip-content':document.getElementById('main-content')?.focus();break;
 case 'switch-user':userSwitcher();break;
 case 'edit-profile':editProfile();break;
 case 'remove-avatar':{const me=user();me.avatar='';save();render(false);toast('Foto profil berhasil dihapus dari demo.');break}
 case 'logout':logoutModal();break;
 case 'confirm-logout':db.sessionActive=false;save();closeModal();go('/login');render();toast('Kamu telah keluar dari pratinjau.');break;
 case 'choose-user':selectUser(id);break;
 case 'close-modal':closeModal();break;
 case 'toggle-theme':setTheme(db.theme==='light'?'dark':'light');break;
 case 'glass-preset':setGlassPreset(id);break;
 case 'toggle-pref':if(a.dataset.key==='anonymous')user().anonymous=!user().anonymous;else db.prefs[a.dataset.key]=!db.prefs[a.dataset.key];save();render(false);toast('Preferensi demo diperbarui.');break;
 case 'init-pay':initPay();break;
 case 'demo-submit':submitPayment(id);break;
 case 'refresh':render(false);toast('Status contoh diperbarui.');break;
 case 'save-qr-preview':saveQR(id);break;
 case 'approve-payment':approvePayment(id);break;
 case 'confirm-approve':confirmApprove(id);break;
 case 'reject-payment':rejectPayment(id);break;
 case 'template-wa':showWa(id);break;
 case 'copy-wa':copyText(waTemplate(id));break;
 case 'open-wa':{const u=db.users.find(x=>x.id===id);if(!u)break;const url=`https://wa.me/?text=${encodeURIComponent(waTemplate(id))}`;window.open(url,'_blank','noopener,noreferrer');toast('WhatsApp dibuka. Pengiriman belum dapat diverifikasi.');break}
 case 'mark-read':db.notifications.filter(n=>n.userId===user().id).forEach(n=>n.read=true);save();render(false);toast('Notifikasi ditandai dibaca.');break;
 case 'pick-avatar':document.getElementById('avatar-picker')?.click();break;
 case 'password-info':infoModal('Keamanan kata sandi','Prototipe menggunakan pilihan akun lokal. Autentikasi NIM, reset token dan hashing password membutuhkan backend produksi, sehingga tombol ini tidak berpura-pura mengganti password.');break;
 case 'reset-demo':modal('Atur ulang pratinjau?',`<p>Semua perubahan lokal, pengajuan dan foto contoh akan kembali ke kondisi awal. Tidak ada akun atau data bank sungguhan yang berubah.</p>`,`<button class="btn btn-outline" data-action="close-modal">Batal</button><button class="btn btn-primary" data-action="confirm-reset">Atur ulang</button>`);break;
 case 'confirm-reset':db=seed();save();closeModal();go('/app');render();toast('Data contoh kembali ke awal.');break;
 case 'new-ticket':newTicket();break;
 case 'resolve-ticket':if(!hasStaff())return;{const t=db.tickets.find(x=>x.id===id);if(t&&t.status==='open'){t.status='closed';audit(`Laporan ${id} selesai`);save();render(false);toast('Laporan ditandai selesai pada demo.')}}break;
 case 'new-member':if(!isChair())toast('Hanya admin keanggotaan berwenang yang bisa menambah akun. Coba mode Kahima.');else newMember();break;
 case 'export-members':csvDownload('kashima-anggota-demo.csv',['nim','nama','angkatan','status'],db.users.map(u=>[u.nim,u.name,u.year,u.active?'aktif':'nonaktif']));break;
 case 'toggle-member':if(!isChair()){toast('Hanya admin berwenang yang dapat mengubah status anggota.');break}{const u=db.users.find(x=>x.id===id);if(u){u.active=!u.active;audit(`Status keanggotaan ${u.name} menjadi ${u.active?'aktif':'nonaktif'}`);save();render(false);toast('Status akun contoh diperbarui.')}}break;
 case 'new-expense':expenseProposal();break;
 case 'export-ledger':csvDownload('kashima-buku-kas-demo.csv',['id','deskripsi','aktor','tanggal','nominal'],ledgerRecords().map(r=>[r.id,r.title,r.person,r.date,r.amount]));break;
 case 'propose-policy':proposePolicy();break;
 case 'approve-proposal':approveProposal(id);break;
 case 'confirm-proposal':{const q=db.proposals.find(x=>x.id===id);if(q&&isChair()&&q.by!==user().id&&q.status==='submitted'){q.status='approved';if(q.kind==='expense')db.expenses.push({id:uid('EXP').toUpperCase(),title:q.title,amount:q.amount,date:new Date().toISOString().slice(0,10),status:'approved',by:q.by});audit(`Kahima menyetujui usulan ${q.id}`);save();closeModal();render(false);toast('Usulan demo disetujui.')}break}
 case 'handover-info':infoModal('Prosedur serah terima','Sebelum berganti pengurus, bendahara harus merekonsiliasi transaksi, menyerahkan laporan dan backup yang diuji, lalu pengurus baru menerima hak akses organisasi. Prosedur ini belum dijalankan oleh prototipe.');break;
 case 'import-csv':infoModal('Impor CSV anggota','Fitur pratinjau ini menyiapkan struktur impor dan validasi format. Untuk menghindari penyalahgunaan data mahasiswa, impor massal tidak diaktifkan tanpa pemeriksaan server dan persetujuan resmi. Anda tetap dapat menambah satu akun contoh.');break;
 case 'print':window.print();break;
 default:break;
}});
document.addEventListener('submit',e=>{const f=e.target;if(!(f instanceof HTMLFormElement))return;switch(f.id){
 case 'profile-form':{e.preventDefault();if(!db.sessionActive)return;const data=new FormData(f),name=String(data.get('name')||'').trim().replace(/\s+/g,' '),nickname=String(data.get('nickname')||'').trim().replace(/\s+/g,' ');if(name.length<3||name.length>70||nickname.length<2||nickname.length>18){toast('Periksa panjang nama lengkap atau panggilan.');return}if(/[<>\x00-\x1f]/.test(name+nickname)){toast('Gunakan karakter nama yang valid.');return}user().name=name;user().nickname=nickname;user().initials=initials(name);save();closeModal();render(false);toast('Identitas profil berhasil diperbarui.');break}
 case 'login-form':{e.preventDefault();const data=new FormData(f),nim=String(data.get('nim')||'');const u=db.users.find(x=>x.nim===nim);if(!u){toast('Gunakan salah satu NIM contoh.');return}selectUser(u.id);break}
 case 'reject-form':{e.preventDefault();const d=new FormData(f),id=String(d.get('id'));const t=getIntent(id);if(!hasStaff()||!t||t.status!=='pending')return;t.status='rejected';audit(`Pengajuan ${id} ditolak: ${String(d.get('reason')).slice(0,120)}`);save();closeModal();render();toast('Pengajuan demo ditolak.');break}
 case 'ticket-form':{e.preventDefault();const d=new FormData(f),obj={id:uid('CASE').toUpperCase(),userId:user().id,title:String(d.get('title')),description:String(d.get('description')),status:'open',createdAt:new Date().toISOString()};db.tickets.unshift(obj);audit(`Laporan ${obj.id} dibuat`);save();closeModal();render(false);toast('Laporan contoh berhasil dibuat.');break}
 case 'member-form':{e.preventDefault();if(!isChair())return;const d=new FormData(f),nim=String(d.get('nim')).trim(),name=String(d.get('name')).trim();if(db.users.some(u=>u.nim===nim)){toast('NIM contoh tersebut sudah terdaftar.');return}const u={id:uid('u'),name,nim,year:String(d.get('year')),role:'member',initials:initials(name),active:true,avatar:'',wa:''};db.users.push(u);/* Anggota baru tidak dikenakan tagihan lama. Jadwal iuran dimulai pada periode berikutnya. */audit(`Anggota contoh ${name} ditambahkan`);save();closeModal();render(false);toast('Anggota contoh berhasil ditambahkan.');break}
 case 'expense-form':{e.preventDefault();if(!hasStaff())return;const d=new FormData(f),amount=Number(d.get('amount'));if(!Number.isFinite(amount)||amount<1000){toast('Masukkan nominal minimal Rp1.000.');return}const q={id:uid('PROP').toUpperCase(),kind:'expense',title:String(d.get('title')).slice(0,100),amount,date:new Date().toISOString(),status:'submitted',by:user().id};db.proposals.unshift(q);audit(`Usulan pengeluaran ${q.id} dibuat`);save();closeModal();render(false);toast('Usulan dikirim ke pusat persetujuan.');break}
 case 'policy-form':{e.preventDefault();if(!hasStaff())return;const d=new FormData(f),q={id:uid('POL').toUpperCase(),kind:'policy',title:String(d.get('title')).slice(0,100),description:String(d.get('description')).slice(0,600),date:new Date().toISOString(),status:'submitted',by:user().id};db.proposals.unshift(q);audit(`Usulan kebijakan ${q.id} dibuat`);save();closeModal();render(false);toast('Usulan contoh berhasil dicatat.');break}
 }});
document.addEventListener('input',e=>{if(e.target.id==='glass-blur-slider'){setGlassBlur(e.target.value);return}if(e.target.id==='member-search'){const q=e.target.value.trim().toLowerCase();const root=document.getElementById('member-results');if(root)root.innerHTML=memberRows(db.users.filter(u=>u.name.toLowerCase().includes(q)||u.nim.includes(q)))}});
document.addEventListener('change',async e=>{if(e.target.id!=='avatar-picker')return;const file=e.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){toast('Gunakan gambar JPG, PNG atau WebP.');return}if(file.size>3*1024*1024){toast('Ukuran maksimal gambar demo 3 MB.');return}try{const data=await new Promise((resolve,reject)=>{const fr=new FileReader();fr.onload=()=>resolve(fr.result);fr.onerror=reject;fr.readAsDataURL(file)});const img=await new Promise((resolve,reject)=>{const x=new Image();x.onload=()=>resolve(x);x.onerror=reject;x.src=data});const c=document.createElement('canvas');c.width=256;c.height=256;const ctx=c.getContext('2d');const s=Math.min(img.width,img.height),x=(img.width-s)/2,y=(img.height-s)/2;ctx.drawImage(img,x,y,s,s,0,0,256,256);user().avatar=c.toDataURL('image/jpeg',.79);save();render(false);toast('Foto profil demo diperbarui.')}catch{toast('Gagal memproses gambar.')}
});
document.addEventListener('keydown',e=>{const dialog=document.querySelector('#modal-root .modal');if(e.key==='Escape'&&dialog){e.preventDefault();closeModal();return}if(e.key==='Tab'&&dialog){const focusables=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')].filter(el=>el.getClientRects().length>0);if(!focusables.length)return;const first=focusables[0],last=focusables[focusables.length-1];if(e.shiftKey&&(document.activeElement===first||document.activeElement===dialog)){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.addEventListener('hashchange',()=>{closeModal();render()});
if(!location.hash)location.hash='#/app';
render();


